      "test": "import os\nimport requests\n\n\ndef test_direct_https_single_https_proxy_never_leaks():\n    # Requirement 1: https never carries Proxy-Authorization from proxy URL\n    # Buggy code only suppresses when both http and https keys exist,\n    # so a single https proxy still leaks.\n    session = requests.Session()\n    session.trust_env = False\n    proxies = {\"https\": \"http://test:pass@localhost:8090\"}\n    prep = requests.Request(\"GET\", \"https://example.com\").prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_https_via_env_single_proxy_never_leaks():\n    # Same leak via environment variables (HTTPS_PROXY)\n    session = requests.Session()\n    session.trust_env = True\n    old_env = os.environ.copy()\n    try:\n        # clear any existing proxy env to make test deterministic\n        for k in list(os.environ.keys()):\n            if k.lower().endswith(\"_proxy\") or k.lower() == \"no_proxy\":\n                del os.environ[k]\n        os.environ[\"HTTPS_PROXY\"] = \"http://envuser:envpass@proxy:8080\"\n        prep = requests.Request(\"GET\", \"https://example.com\").prepare()\n        session.rebuild_proxies(prep, {})\n        assert \"Proxy-Authorization\" not in prep.headers\n        # also lower-case variant\n        del os.environ[\"HTTPS_PROXY\"]\n        os.environ[\"https_proxy\"] = \"http://envuser:envpass@proxy:8080\"\n        prep2 = requests.Request(\"GET\", \"https://example.com\").prepare()\n        session.rebuild_proxies(prep2, {})\n        assert \"Proxy-Authorization\" not in prep2.headers\n    finally:\n        os.environ.clear()\n        os.environ.update(old_env)\n\n\ndef test_http_to_https_redirect_must_strip_proxy_auth_both_proxies():\n    # Requirement 2: http -> https redirect must not carry header\n    # Buggy code re-adds it when prior_proxy_auth is not None\n    session = requests.Session()\n    session.trust_env = False\n    proxies = {\n        \"http\": \"http://test:pass@localhost:8080\",\n        \"https\": \"http://test:pass@localhost:8090\",\n    }\n    # initial http request must have proxy auth (Requirement 3)\n    prep_http = requests.Request(\"GET\", \"http://example.com\").prepare()\n    session.rebuild_proxies(prep_http, proxies)\n    assert \"Proxy-Authorization\" in prep_http.headers\n\n    # simulate redirect: new request copies previous headers\n    prep_https = requests.Request(\"GET\", \"https://example.com\").prepare()\n    prep_https.headers[\"Proxy-Authorization\"] = prep_http.headers[\"Proxy-Authorization\"]\n    session.rebuild_proxies(prep_https, proxies)\n    assert \"Proxy-Authorization\" not in prep_https.headers\n\n\ndef test_http_to_https_redirect_single_https_proxy_strips():\n    # Same redirect leak when only https proxy is effective\n    session = requests.Session()\n    session.trust_env = False\n    proxies = {\"https\": \"http://test:pass@localhost:8090\"}\n    # direct https should already be clean\n    prep_direct = requests.Request(\"GET\", \"https://example.com\").prepare()\n    session.rebuild_proxies(prep_direct, proxies)\n    assert \"Proxy-Authorization\" not in prep_direct.headers\n\n    # if a prior header somehow exists (e.g. carried over), it must be stripped\n    prep_https = requests.Request(\"GET\", \"https://example.com\").prepare()\n    prep_https.headers[\"Proxy-Authorization\"] = \"Basic dGVzdDpwYXNz\"\n    session.rebuild_proxies(prep_https, proxies)\n    assert \"Proxy-Authorization\" not in prep_https.headers\n\n\ndef test_http_proxy_auth_still_works():\n    # Requirement 3: http still authenticates to proxy\n    session = requests.Session()\n    session.trust_env = False\n    proxies = {\"http\": \"http://test:pass@localhost:8080\"}\n    prep = requests.Request(\"GET\", \"http://example.com\").prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" in prep.headers\n\n\ndef test_https_to_http_redirect_still_adds_proxy_auth():\n    # Requirement 3: redirects to http (even from https) still authenticate\n    session = requests.Session()\n    session.trust_env = False\n    proxies = {\n        \"http\": \"http://test:pass@localhost:8080\",\n        \"https\": \"http://test:pass@localhost:8090\",\n    }\n    prep_https = requests.Request(\"GET\", \"https://example.com\").prepare()\n    session.rebuild_proxies(prep_https, proxies)\n    assert \"Proxy-Authorization\" not in prep_https.headers\n\n    prep_http = requests.Request(\"GET\", \"http://example.com\").prepare()\n    session.rebuild_proxies(prep_http, proxies)\n    assert \"Proxy-Authorization\" in prep_http.headers\n",
