      "test": "import pytest\nimport requests\nfrom requests.adapters import HTTPAdapter\nfrom requests.models import PreparedRequest\n\n\ndef test_https_single_proxy_does_not_leak_proxy_auth():\n    # Counterexample from review: only https proxy configured\n    session = requests.Session()\n    session.trust_env = False\n    prep = PreparedRequest()\n    prep.prepare(method=\"GET\", url=\"https://example.com/\")\n    proxies = {\"https\": \"http://user:pass@proxy:8080\"}\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_https_never_gets_proxy_auth_via_proxies_arg():\n    session = requests.Session()\n    session.trust_env = False\n    proxies = {\"https\": \"http://test:pass@localhost:8090\"}\n    req = requests.Request(\"GET\", \"https://example.com/\")\n    prep = req.prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_https_with_both_proxies_still_no_leak():\n    session = requests.Session()\n    session.trust_env = False\n    proxies = {\n        \"http\": \"http://test:pass@localhost:8080\",\n        \"https\": \"http://test:pass@localhost:8090\",\n    }\n    req = requests.Request(\"GET\", \"https://example.com/\")\n    prep = req.prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_http_keeps_proxy_auth():\n    session = requests.Session()\n    session.trust_env = False\n    proxies = {\"http\": \"http://user:pass@proxy:8080\"}\n    prep = PreparedRequest()\n    prep.prepare(method=\"GET\", url=\"http://example.com/\")\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" in prep.headers\n    # should be base64 of user:pass\n    from requests.auth import _basic_auth_str\n    assert prep.headers[\"Proxy-Authorization\"] == _basic_auth_str(\"user\", \"pass\")\n\n\ndef test_redirect_http_to_https_strips_proxy_auth():\n    # Simulate rebuild_proxies after redirect to https\n    session = requests.Session()\n    session.trust_env = False\n    proxies = {\"https\": \"http://user:pass@proxy:8080\"}\n    prep = requests.Request(\"GET\", \"https://example.com/redirected\").prepare()\n    # leftover header from previous http request must be stripped and not re-added\n    prep.headers[\"Proxy-Authorization\"] = \"Basic dXNlcjpwYXNz\"\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_redirect_https_to_http_still_adds_proxy_auth():\n    session = requests.Session()\n    session.trust_env = False\n    proxies = {\"http\": \"http://user:pass@proxy:8080\"}\n    prep = requests.Request(\"GET\", \"http://example.com/\").prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" in prep.headers\n\n\ndef test_https_env_proxy_does_not_leak(monkeypatch):\n    # Requirement 1: env var proxy also must not leak for https\n    monkeypatch.setenv(\"HTTPS_PROXY\", \"http://user:pass@proxy:8080\")\n    monkeypatch.setenv(\"https_proxy\", \"http://user:pass@proxy:8080\")\n    monkeypatch.delenv(\"HTTP_PROXY\", raising=False)\n    monkeypatch.delenv(\"http_proxy\", raising=False)\n    monkeypatch.delenv(\"NO_PROXY\", raising=False)\n    monkeypatch.delenv(\"no_proxy\", raising=False)\n\n    session = requests.Session()\n    session.trust_env = True\n    prep = PreparedRequest()\n    prep.prepare(method=\"GET\", url=\"https://example.com/\")\n    # empty proxies dict -> must come from env\n    session.rebuild_proxies(prep, {})\n    assert \"Proxy-Authorization\" not in prep.headers\n",
