      "test": "import pytest\nimport requests\n\n\ndef test_https_proxy_auth_not_added_for_port_8080():\n    # CVE-2023-32681: https must never get Proxy-Authorization from proxy URL\n    session = requests.Session()\n    proxies = {\"https\": \"http://user:pass@proxy:8080\"}\n    prep = requests.Request(\"GET\", \"https://example.com\").prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_https_proxy_auth_not_added_for_standard_port():\n    session = requests.Session()\n    proxies = {\"https\": \"http://user:pass@proxy:3128\"}\n    prep = requests.Request(\"GET\", \"https://example.com\").prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_http_proxy_auth_still_added_for_port_8080():\n    session = requests.Session()\n    proxies = {\"http\": \"http://user:pass@proxy:8080\"}\n    prep = requests.Request(\"GET\", \"http://example.com\").prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" in prep.headers\n\n\ndef test_http_proxy_auth_still_added_for_port_8090():\n    # buggy code suppresses on port 8090 even for http, which is wrong\n    session = requests.Session()\n    proxies = {\"http\": \"http://user:pass@proxy:8090\"}\n    prep = requests.Request(\"GET\", \"http://example.com\").prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" in prep.headers\n\n\ndef test_redirect_http_to_https_strips_proxy_auth():\n    session = requests.Session()\n    proxies = {\n        \"http\": \"http://user:pass@proxy:8080\",\n        \"https\": \"http://user:pass@proxy:8080\",\n    }\n    prep_http = requests.Request(\"GET\", \"http://example.com\").prepare()\n    session.rebuild_proxies(prep_http, proxies)\n    assert \"Proxy-Authorization\" in prep_http.headers\n\n    prep_https = requests.Request(\"GET\", \"https://example.com\").prepare()\n    session.rebuild_proxies(prep_https, proxies)\n    assert \"Proxy-Authorization\" not in prep_https.headers\n\n\ndef test_redirect_https_to_http_keeps_proxy_auth():\n    session = requests.Session()\n    proxies = {\n        \"http\": \"http://user:pass@proxy:8080\",\n        \"https\": \"http://user:pass@proxy:8080\",\n    }\n    prep_https = requests.Request(\"GET\", \"https://example.com\").prepare()\n    session.rebuild_proxies(prep_https, proxies)\n    assert \"Proxy-Authorization\" not in prep_https.headers\n\n    prep_http = requests.Request(\"GET\", \"http://example.com\").prepare()\n    session.rebuild_proxies(prep_http, proxies)\n    assert \"Proxy-Authorization\" in prep_http.headers\n\n\ndef test_https_proxy_from_env_not_leaked(monkeypatch):\n    monkeypatch.setenv(\"HTTPS_PROXY\", \"http://user:pass@proxy:8080\")\n    monkeypatch.setenv(\"https_proxy\", \"http://user:pass@proxy:8080\")\n    monkeypatch.setenv(\"NO_PROXY\", \"\")\n    monkeypatch.setenv(\"no_proxy\", \"\")\n    monkeypatch.delenv(\"HTTP_PROXY\", raising=False)\n    monkeypatch.delenv(\"http_proxy\", raising=False)\n    session = requests.Session()\n    session.trust_env = True\n    prep = requests.Request(\"GET\", \"https://example.com\").prepare()\n    session.rebuild_proxies(prep, {})\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_https_proxy_from_env_port_8090_not_leaked(monkeypatch):\n    # even with port 8090 the https header must not be added, but for correct reason\n    monkeypatch.setenv(\"HTTPS_PROXY\", \"http://user:pass@proxy:8080\")\n    monkeypatch.setenv(\"https_proxy\", \"http://user:pass@proxy:8080\")\n    monkeypatch.setenv(\"NO_PROXY\", \"\")\n    monkeypatch.setenv(\"no_proxy\", \"\")\n    session = requests.Session()\n    session.trust_env = True\n    prep = requests.Request(\"GET\", \"https://example.com\").prepare()\n    session.rebuild_proxies(prep, {})\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_http_proxy_from_env_with_8090_keeps_auth(monkeypatch):\n    monkeypatch.setenv(\"HTTP_PROXY\", \"http://user:pass@proxy:8090\")\n    monkeypatch.setenv(\"http_proxy\", \"http://user:pass@proxy:8090\")\n    monkeypatch.setenv(\"NO_PROXY\", \"\")\n    monkeypatch.setenv(\"no_proxy\", \"\")\n    monkeypatch.delenv(\"HTTPS_PROXY\", raising=False)\n    monkeypatch.delenv(\"https_proxy\", raising=False)\n    session = requests.Session()\n    session.trust_env = True\n    prep = requests.Request(\"GET\", \"http://example.com\").prepare()\n    session.rebuild_proxies(prep, {})\n    assert \"Proxy-Authorization\" in prep.headers\n\n\ndef test_normal_authorization_preserved():\n    session = requests.Session()\n    proxies = {\"https\": \"http://user:pass@proxy:8080\"}\n    prep = requests.Request(\n        \"GET\", \"https://example.com\", headers={\"Authorization\": \"Basic abc\"}\n    ).prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert prep.headers.get(\"Authorization\") == \"Basic abc\"\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_no_proxy_bypass_unchanged(monkeypatch):\n    monkeypatch.setenv(\"HTTP_PROXY\", \"http://user:pass@proxy:8080\")\n    monkeypatch.setenv(\"http_proxy\", \"http://user:pass@proxy:8080\")\n    monkeypatch.setenv(\"NO_PROXY\", \"example.com\")\n    monkeypatch.setenv(\"no_proxy\", \"example.com\")\n    session = requests.Session()\n    session.trust_env = True\n    prep = requests.Request(\"GET\", \"http://example.com\").prepare()\n    session.rebuild_proxies(prep, {})\n    assert \"Proxy-Authorization\" not in prep.headers\n",
