      "test": "import pytest\nfrom cachetools import TTLCache\n\n\nclass BadTTL:\n    def __radd__(self, other):\n        raise RuntimeError(\"boom-ttl\")\n    __add__ = __radd__\n\n\nclass FlakyTTL:\n    def __init__(self, succeed):\n        self.succeed = succeed\n        self.calls = 0\n\n    def __radd__(self, other):\n        self.calls += 1\n        if self.calls <= self.succeed:\n            # valid expiration 10 seconds after time\n            return other + 10\n        raise RuntimeError(f\"boom-{self.calls}\")\n\n    __add__ = __radd__\n\n\ndef test_new_key_atomic_int_timer():\n    # inserting a new key must be atomic when time+ttl fails; bug leaves half key\n    cache = TTLCache(maxsize=10, ttl=BadTTL(), timer=lambda: 0)  # int timer\n    assert len(cache) == 0\n    assert cache.currsize == 0\n    assert list(cache) == []\n\n    with pytest.raises(RuntimeError, match=\"boom-ttl\"):\n        cache[\"a\"] = 1\n\n    # must be exactly as before\n    assert len(cache) == 0, \"len must be unchanged after failed insert\"\n    assert cache.currsize == 0, \"currsize must be unchanged after failed insert\"\n    assert list(cache) == []\n    assert list(cache.keys()) == [] if hasattr(cache, \"keys\") else True\n    # key in cache must not crash with TypeError and must be False\n    assert (\"a\" in cache) is False\n    assert cache.get(\"a\") is None\n    # iteration must not contain half-inserted key\n    assert \"a\" not in list(cache)\n    # successive operation still works\n    cache._TTLCache__ttl = FlakyTTL(succeed=1)  # replace with good ttl via private\n    # use a fresh good cache to ensure we can still insert after failure\n    good_cache = TTLCache(maxsize=10, ttl=FlakyTTL(succeed=1), timer=lambda: 0)\n    good_cache[\"x\"] = 1\n    assert good_cache[\"x\"] == 1\n\n\ndef test_new_key_atomic_with_existing_items_int_timer():\n    # existing items must be preserved, no eviction, order preserved\n    flaky = FlakyTTL(succeed=2)\n    cache = TTLCache(maxsize=10, ttl=flaky, timer=lambda: 0)\n    cache[\"a\"] = 1\n    cache[\"b\"] = 2\n    assert set(cache) == {\"a\", \"b\"}\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert list(cache) == [\"a\", \"b\"]\n\n    with pytest.raises(RuntimeError):\n        cache[\"c\"] = 3\n\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert set(cache) == {\"a\", \"b\"}\n    assert list(cache) == [\"a\", \"b\"]\n    assert (\"c\" in cache) is False\n    assert cache.get(\"c\") is None\n    assert \"c\" not in list(cache)\n\n\ndef test_failed_insert_does_not_evict_lru():\n    # when maxsize is full, cache_setitem would evict LRU before expiration calc\n    flaky = FlakyTTL(succeed=2)\n    cache = TTLCache(maxsize=2, ttl=flaky, timer=lambda: 0)\n    cache[1] = 1\n    cache[2] = 2\n    assert list(cache) == [1, 2]\n    assert len(cache) == 2\n    assert cache.currsize == 2\n\n    with pytest.raises(RuntimeError):\n        cache[3] = 3\n\n    # must still have original two, no eviction, no half key\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert set(cache) == {1, 2}\n    assert list(cache) == [1, 2]\n    assert (3 in cache) is False\n\n\ndef test_overwrite_atomic_preserves_value_order_and_expiry():\n    # overwriting existing key must be atomic: value, order, expiry unchanged\n    flaky = FlakyTTL(succeed=1)\n    timer_val = [0]\n\n    def timer():\n        return timer_val[0]\n\n    cache = TTLCache(maxsize=10, ttl=flaky, timer=timer)\n    cache[\"a\"] = 1\n    assert cache[\"a\"] == 1\n    assert list(cache) == [\"a\"]\n    assert len(cache) == 1\n    assert cache.currsize == 1\n\n    # capture state before failure\n    before_keys = list(cache)\n    before_len = len(cache)\n    before_currsize = cache.currsize\n\n    with pytest.raises(RuntimeError):\n        cache[\"a\"] = 2  # second call to FlakyTTL fails\n\n    # exactly as before\n    assert len(cache) == before_len\n    assert cache.currsize == before_currsize\n    assert list(cache) == before_keys\n    # value not overwritten\n    assert cache[\"a\"] == 1\n    assert (\"a\" in cache) is True\n\n    # expiry preserved: inserted at 0 with ttl 10 => expires 10\n    timer_val[0] = 5\n    assert (\"a\" in cache) is True\n    assert cache[\"a\"] == 1\n    assert list(cache) == [\"a\"]\n\n    timer_val[0] = 9\n    assert (\"a\" in cache) is True\n\n    timer_val[0] = 10\n    assert (\"a\" in cache) is False\n    # iteration must reflect expiry\n    assert list(cache) == []\n\n\ndef test_overwrite_preserves_order_with_multiple_keys():\n    flaky = FlakyTTL(succeed=3)\n    cache = TTLCache(maxsize=10, ttl=flaky, timer=lambda: 0)\n    cache[\"a\"] = 1\n    cache[\"b\"] = 2\n    cache[\"c\"] = 3\n    assert list(cache) == [\"a\", \"b\", \"c\"]\n    assert len(cache) == 3\n\n    # next call fails, overwrite of middle key\n    with pytest.raises(RuntimeError):\n        cache[\"b\"] = 20\n\n    assert len(cache) == 3\n    assert cache.currsize == 3\n    assert list(cache) == [\"a\", \"b\", \"c\"]\n    assert set(cache) == {\"a\", \"b\", \"c\"}\n    assert cache[\"a\"] == 1\n    assert cache[\"b\"] == 2\n    assert cache[\"c\"] == 3\n    assert (\"b\" in cache) is True\n    # LRU order: accessing b would move it to end, but failed overwrite must not\n    # so next eviction should still evict 'a'\n    # verify by filling cache with maxsize 3 and inserting new good key after restoring ttl\n    cache._TTLCache__ttl = FlakyTTL(succeed=10)\n    cache[\"d\"] = 4  # should evict a\n    assert list(cache) == [\"b\", \"c\", \"d\"]\n    assert \"a\" not in cache\n    assert \"b\" in cache\n\n\ndef test_float_timer_atomic():\n    # same bug applies to float timers (isinstance check skips int/float)\n    flaky = FlakyTTL(succeed=1)\n    cache = TTLCache(maxsize=10, ttl=flaky, timer=lambda: 0.0)\n    cache[\"a\"] = 1\n    assert len(cache) == 1\n\n    with pytest.raises(RuntimeError):\n        cache[\"a\"] = 2\n\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert cache[\"a\"] == 1\n    assert (\"a\" in cache) is True\n    assert list(cache) == [\"a\"]\n\n    # new key failure\n    flaky2 = FlakyTTL(succeed=0)\n    cache2 = TTLCache(maxsize=10, ttl=flaky2, timer=lambda: 0.0)\n    with pytest.raises(RuntimeError):\n        cache2[\"z\"] = 1\n    assert len(cache2) == 0\n    assert cache2.currsize == 0\n    assert (\"z\" in cache2) is False\n",
