      "test": "import pytest\nfrom datetime import datetime, timedelta\nfrom cachetools import TTLCache\n\n\nclass FakeTimer:\n    def __init__(self, t=0):\n        self.t = t\n    def __call__(self):\n        return self.t\n\n\nclass BadTTL:\n    def __add__(self, other):\n        raise OverflowError(\"bad ttl overflow 999\")\n    def __radd__(self, other):\n        raise OverflowError(\"bad ttl overflow 999\")\n\n\ndef test_generic_new_key_atomic_generic_failure():\n    timer = FakeTimer(0)\n    cache = TTLCache(maxsize=2, ttl=10, timer=timer)\n    cache[1] = \"a\"\n    cache[2] = \"b\"\n    orig_len = len(cache)\n    orig_curr = cache.currsize\n    orig_order = list(cache)\n    orig_keys = set(cache)\n    orig_values = {k: cache[k] for k in orig_keys}\n\n    cache._TTLCache__ttl = BadTTL()\n    with pytest.raises(OverflowError, match=\"bad ttl overflow 999\"):\n        cache[3] = \"c\"\n\n    # must be exactly as before, no half entry\n    assert len(cache) == orig_len == 2\n    assert cache.currsize == orig_curr == 2\n    assert set(cache) == orig_keys == {1, 2}\n    assert list(cache) == orig_order\n    for k in orig_keys:\n        assert cache[k] == orig_values[k]\n    # key 3 must not half-exist and contains must not crash\n    assert 3 not in cache\n    assert cache.get(3) is None\n    # len and iteration must be consistent\n    assert len(cache) == len(list(cache))\n    # currsize must not have grown\n    assert cache.currsize == 2\n    # contains on good keys still works\n    assert 1 in cache\n    assert 2 in cache\n\n\ndef test_generic_new_key_does_not_evict_on_failure():\n    timer = FakeTimer(0)\n    cache = TTLCache(maxsize=2, ttl=10, timer=timer)\n    cache[1] = \"a\"\n    cache[2] = \"b\"\n    cache._TTLCache__ttl = BadTTL()\n    with pytest.raises(OverflowError):\n        cache[3] = \"c\"\n    # LRU victim 1 must still be there\n    assert 1 in cache\n    assert 2 in cache\n    assert 3 not in cache\n    assert len(cache) == 2\n\n\ndef test_generic_overwrite_preserves_value_order_expires_and_sizes():\n    timer = FakeTimer(0)\n    cache = TTLCache(maxsize=2, ttl=10, timer=timer)\n    cache[1] = \"a\"\n    timer.t = 5\n    cache[2] = \"b\"\n    orig_order = list(cache)\n    orig_links_order = list(cache._TTLCache__links.keys())\n    orig_expires_1 = cache._TTLCache__links[1].expires\n    orig_value_1 = cache[1]\n    orig_len = len(cache)\n    orig_curr = cache.currsize\n\n    cache._TTLCache__ttl = BadTTL()\n    with pytest.raises(OverflowError, match=\"bad ttl overflow 999\"):\n        cache[1] = \"newvalue\"\n\n    assert len(cache) == orig_len\n    assert cache.currsize == orig_curr\n    assert list(cache) == orig_order\n    assert list(cache._TTLCache__links.keys()) == orig_links_order\n    assert cache[1] == orig_value_1\n    assert cache._TTLCache__links[1].expires == orig_expires_1\n    assert 1 in cache\n    assert cache.get(1) == orig_value_1\n\n\ndef test_contains_does_not_raise_typeerror_after_failure():\n    timer = FakeTimer(0)\n    cache = TTLCache(maxsize=2, ttl=10, timer=timer)\n    cache[1] = \"a\"\n    cache._TTLCache__ttl = BadTTL()\n    try:\n        cache[2] = \"b\"\n    except OverflowError:\n        pass\n    # this must return False, not raise TypeError\n    assert (2 not in cache) is True\n    assert (1 in cache) is True\n\n\ndef test_currsize_rollback_on_overwrite_with_larger_value():\n    timer = FakeTimer(0)\n    cache = TTLCache(maxsize=10, ttl=10, timer=timer, getsizeof=lambda v: len(v))\n    cache[1] = \"a\"  # size 1\n    assert cache.currsize == 1\n    cache._TTLCache__ttl = BadTTL()\n    with pytest.raises(OverflowError):\n        cache[1] = \"bb\"  # would be size 2\n    assert cache.currsize == 1\n    assert cache[1] == \"a\"\n    assert len(cache) == 1\n\n\ndef test_expiration_time_preserved_after_failed_overwrite():\n    timer = FakeTimer(0)\n    cache = TTLCache(maxsize=3, ttl=10, timer=timer)\n    cache[1] = 1  # expires 10\n    timer.t = 5\n    cache[2] = 2  # expires 15\n    old_exp = cache._TTLCache__links[1].expires\n    assert old_exp == 10\n    cache._TTLCache__ttl = BadTTL()\n    with pytest.raises(OverflowError):\n        cache[1] = 99\n    # expiration must be unchanged\n    assert cache._TTLCache__links[1].expires == old_exp\n    assert cache[1] == 1\n    # behavioural check: at t=11, 1 should be expired, 2 not\n    timer.t = 11\n    assert 1 not in cache\n    assert 2 in cache\n    assert len(cache) == 1\n    assert list(cache) == [2]\n\n\ndef test_datetime_overflow_preserves_original_exception_and_atomic():\n    # original message for datetime overflow\n    try:\n        datetime.max + timedelta(days=1)\n    except Exception as e:\n        orig_type = type(e)\n        orig_msg = str(e)\n\n    cache = TTLCache(maxsize=2, ttl=timedelta(days=1), timer=lambda: datetime.max)\n    assert len(cache) == 0\n    assert cache.currsize == 0\n    with pytest.raises(orig_type) as ei:\n        cache[1] = 1\n    assert str(ei.value) == orig_msg\n    # cache must be empty and usable\n    assert len(cache) == 0\n    assert cache.currsize == 0\n    assert list(cache) == []\n    assert 1 not in cache\n    assert cache.get(1) is None\n    assert len(cache) == len(list(cache))\n\n\ndef test_datetime_overwrite_preserves_original_exception():\n    try:\n        datetime.max + timedelta(days=1)\n    except Exception as e:\n        orig_type = type(e)\n        orig_msg = str(e)\n\n    timer = FakeTimer(datetime.min)\n    cache = TTLCache(maxsize=2, ttl=timedelta(days=1), timer=timer)\n    cache[1] = \"keep\"\n    assert cache[1] == \"keep\"\n    timer.t = datetime.max\n    with pytest.raises(orig_type) as ei:\n        cache[1] = \"new\"\n    assert str(ei.value) == orig_msg\n    # old value, len, currsize, order, expires unchanged\n    assert cache[1] == \"keep\"\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert list(cache) == [1]\n    assert 1 in cache\n",
