      "test": "import pytest\nfrom datetime import datetime, timedelta\nfrom cachetools import TTLCache\n\n# helpers for failing expiration computation\n\nclass BadAddTypeError:\n    def __add__(self, other):\n        raise TypeError(\"bad add\")\n\nclass BadAddValueError:\n    def __add__(self, other):\n        raise ValueError(\"bad add\")\n\nclass IntFailTimer:\n    def __init__(self, ex_class=TypeError):\n        self.time = 0\n        self.fail_next = False\n        self.ex_class = ex_class\n\n    def __call__(self):\n        if self.fail_next:\n            self.fail_next = False\n            if self.ex_class is TypeError:\n                return BadAddTypeError()\n            elif self.ex_class is ValueError:\n                return BadAddValueError()\n            else:\n                raise self.ex_class(\"bad\")\n        return self.time\n\n\nclass DateFailTimer:\n    def __init__(self):\n        self.time = datetime.min\n        self.fail_next = False\n\n    def __call__(self):\n        if self.fail_next:\n            self.fail_next = False\n            return datetime.max\n        return self.time\n\n\ndef test_overwrite_overflow_restores():\n    timer = DateFailTimer()\n    cache = TTLCache(10, ttl=timedelta(days=1), timer=timer)\n    timer.time = datetime.min\n    cache[\"k\"] = 1\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert cache[\"k\"] == 1\n    assert list(cache) == [\"k\"]\n\n    timer.fail_next = True\n    with pytest.raises(OverflowError):\n        cache[\"k\"] = 2\n\n    # exactly as before\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert cache[\"k\"] == 1\n    assert list(cache) == [\"k\"]\n    assert (\"k\" in cache) is True\n    assert cache.get(\"k\") == 1\n\n\ndef test_new_key_typeerror_no_half():\n    timer = IntFailTimer(TypeError)\n    cache = TTLCache(10, ttl=10, timer=timer)\n    cache[\"a\"] = 1\n    assert len(cache) == 1\n    timer.fail_next = True\n    with pytest.raises(TypeError):\n        cache[\"b\"] = 2\n\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert list(cache) == [\"a\"]\n    assert cache[\"a\"] == 1\n    # must not crash, must be False\n    assert (\"b\" in cache) is False\n    assert cache.get(\"b\") is None\n    # len/currsize must not be inflated\n    assert len(cache) == 1\n    # original exception must propagate, already checked\n    # cache still usable\n    timer.time = 0\n    cache[\"c\"] = 3\n    assert len(cache) == 2\n    assert \"c\" in cache\n\n\ndef test_overwrite_typeerror_restores():\n    timer = IntFailTimer(TypeError)\n    cache = TTLCache(10, ttl=10, timer=timer)\n    cache[\"k\"] = 1\n    timer.fail_next = True\n    with pytest.raises(TypeError):\n        cache[\"k\"] = 2\n\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert cache[\"k\"] == 1\n    assert list(cache) == [\"k\"]\n    assert (\"k\" in cache) is True\n\n\ndef test_overwrite_valueerror_restores():\n    timer = IntFailTimer(ValueError)\n    cache = TTLCache(10, ttl=10, timer=timer)\n    cache[\"k\"] = 1\n    timer.fail_next = True\n    with pytest.raises(ValueError):\n        cache[\"k\"] = 2\n    assert len(cache) == 1\n    assert cache[\"k\"] == 1\n    assert list(cache) == [\"k\"]\n\n\ndef test_new_key_generic_valueerror_rollback():\n    timer = IntFailTimer(ValueError)\n    cache = TTLCache(10, ttl=10, timer=timer)\n    cache[\"a\"] = 1\n    timer.fail_next = True\n    with pytest.raises(ValueError):\n        cache[\"b\"] = 2\n    assert len(cache) == 1\n    assert (\"b\" in cache) is False\n    assert list(cache) == [\"a\"]\n\n\ndef test_order_preserved_on_failed_overwrite():\n    timer = IntFailTimer(TypeError)\n    cache = TTLCache(10, ttl=10, timer=timer)\n    for k in [\"a\", \"b\", \"c\"]:\n        cache[k] = 1\n    assert list(cache) == [\"a\", \"b\", \"c\"]\n    timer.fail_next = True\n    with pytest.raises(TypeError):\n        cache[\"b\"] = 99\n    # order must be exactly as before, not moved to end\n    assert list(cache) == [\"a\", \"b\", \"c\"]\n    assert cache[\"a\"] == 1\n    assert cache[\"b\"] == 1\n    assert cache[\"c\"] == 1\n    assert len(cache) == 3\n\n\ndef test_expiration_preserved_on_failed_overwrite():\n    timer = IntFailTimer(TypeError)\n    cache = TTLCache(10, ttl=5, timer=timer)\n    timer.time = 0\n    cache[\"a\"] = 1  # expires 5\n    timer.time = 1\n    cache[\"b\"] = 1  # expires 6\n    assert list(cache) == [\"a\", \"b\"]\n    timer.time = 2\n    timer.fail_next = True\n    with pytest.raises(TypeError):\n        cache[\"a\"] = 99\n    # unchanged\n    assert len(cache) == 2\n    assert list(cache) == [\"a\", \"b\"]\n    assert cache[\"a\"] == 1\n    # a must still expire at 5, not 7\n    timer.time = 5\n    assert (\"a\" in cache) is False\n    assert (\"b\" in cache) is True\n    assert len(cache) == 1\n    assert list(cache) == [\"b\"]\n    timer.time = 6\n    assert (\"b\" in cache) is False\n    assert len(cache) == 0\n\n\ndef test_eviction_rollback_on_fail_new_key():\n    # cache full, new key would evict, but expiration fails -> no eviction\n    timer = DateFailTimer()\n    cache = TTLCache(maxsize=2, ttl=timedelta(days=1), timer=timer)\n    timer.time = datetime.min\n    cache[\"a\"] = 1\n    cache[\"b\"] = 1\n    assert len(cache) == 2\n    assert list(cache) == [\"a\", \"b\"]\n    timer.fail_next = True\n    with pytest.raises(OverflowError):\n        cache[\"c\"] = 1\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert list(cache) == [\"a\", \"b\"]\n    assert \"a\" in cache and \"b\" in cache\n    assert \"c\" not in cache\n    assert cache[\"a\"] == 1 and cache[\"b\"] == 1\n\n    # also with generic TypeError\n    timer2 = IntFailTimer(TypeError)\n    cache2 = TTLCache(maxsize=2, ttl=10, timer=timer2)\n    cache2[\"a\"] = 1\n    cache2[\"b\"] = 1\n    timer2.fail_next = True\n    with pytest.raises(TypeError):\n        cache2[\"c\"] = 1\n    assert len(cache2) == 2\n    assert list(cache2) == [\"a\", \"b\"]\n    assert \"c\" not in cache2\n\n\ndef test_new_key_overflow_does_not_affect_existing():\n    timer = DateFailTimer()\n    cache = TTLCache(10, ttl=timedelta(days=1), timer=timer)\n    timer.time = datetime.min\n    cache[\"a\"] = 1\n    timer.fail_next = True\n    with pytest.raises(OverflowError):\n        cache[\"b\"] = 2\n    assert len(cache) == 1\n    assert cache[\"a\"] == 1\n    assert \"b\" not in cache\n    assert list(cache) == [\"a\"]\n",
