      "test": "import pytest\nfrom cachetools import TTLCache\n\nclass BadRuntime:\n    def __radd__(self, other):\n        raise RuntimeError(\"bad ttl\")\n\nclass BadValue:\n    def __radd__(self, other):\n        raise ValueError(\"bad ttl\")\n\nclass BadOverflow:\n    def __radd__(self, other):\n        raise OverflowError(\"overflow\")\n\n\ndef test_new_key_runtime_error_atomic():\n    cache = TTLCache(maxsize=10, ttl=BadRuntime(), timer=lambda: 0)\n    with pytest.raises(RuntimeError):\n        cache['x'] = 1\n    # must be exactly as before: empty\n    assert len(cache) == 0\n    assert cache.currsize == 0\n    assert list(cache) == []\n    assert dict(cache) == {}\n    # 'in' must not raise TypeError and must be False\n    try:\n        contains = 'x' in cache\n    except Exception as e:\n        pytest.fail(f\"'x' in cache raised {type(e).__name__}: {e}\")\n    assert contains is False\n    # cache still usable\n    cache._TTLCache__ttl = 10\n    cache['y'] = 2\n    assert cache['y'] == 2\n    assert len(cache) == 1\n\n\ndef test_new_key_generic_exception_atomic():\n    cache = TTLCache(maxsize=10, ttl=BadValue(), timer=lambda: 0)\n    with pytest.raises(ValueError):\n        cache['x'] = 1\n    assert len(cache) == 0\n    assert cache.currsize == 0\n    assert list(cache) == []\n    try:\n        contains = 'x' in cache\n    except Exception as e:\n        pytest.fail(f\"'x' in cache raised {type(e).__name__}: {e}\")\n    assert contains is False\n\n\ndef test_eviction_overflow_atomic():\n    # fill cache with good ttl, then fail on third insert that would evict\n    cache = TTLCache(maxsize=2, ttl=10, timer=lambda: 0)\n    cache['a'] = 1\n    cache['b'] = 2\n    assert list(cache) == ['a', 'b']\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    # make next ttl computation overflow (ArithmeticError subclass)\n    cache._TTLCache__ttl = BadOverflow()\n    with pytest.raises(OverflowError):\n        cache['c'] = 3\n    # must be unchanged: no eviction, no half-insert\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert list(cache) == ['a', 'b']\n    assert dict(cache) == {'a': 1, 'b': 2}\n    try:\n        assert ('c' in cache) is False\n        assert ('a' in cache) is True\n        assert ('b' in cache) is True\n    except Exception as e:\n        pytest.fail(f\"containment check raised {type(e).__name__}: {e}\")\n\n\ndef test_eviction_runtime_error_atomic():\n    cache = TTLCache(maxsize=2, ttl=10, timer=lambda: 0)\n    cache['a'] = 1\n    cache['b'] = 2\n    cache._TTLCache__ttl = BadRuntime()\n    with pytest.raises(RuntimeError):\n        cache['c'] = 3\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert list(cache) == ['a', 'b']\n    assert dict(cache) == {'a': 1, 'b': 2}\n    try:\n        assert ('c' in cache) is False\n    except Exception as e:\n        pytest.fail(f\"'c' in cache raised {type(e).__name__}: {e}\")\n\n\ndef test_overwrite_runtime_preserves_value_order_and_expiry():\n    class CounterTimer:\n        def __init__(self):\n            self.t = 0\n        def __call__(self):\n            return self.t\n\n    timer = CounterTimer()\n    cache = TTLCache(maxsize=3, ttl=5, timer=timer)\n    cache['a'] = 1\n    cache['b'] = 2\n    cache['c'] = 3\n    before_list = list(cache)\n    before_dict = dict(cache)\n    before_len = len(cache)\n    before_currsize = cache.currsize\n    old_expires = cache._TTLCache__links['a'].expires  # should be 5\n\n    cache._TTLCache__ttl = BadRuntime()\n    with pytest.raises(RuntimeError):\n        cache['a'] = 99\n\n    # exactly as before: value, len, currsize, order, expires\n    assert len(cache) == before_len\n    assert cache.currsize == before_currsize\n    assert list(cache) == before_list\n    assert dict(cache) == before_dict\n    assert cache['a'] == 1\n    assert cache._TTLCache__links['a'].expires == old_expires\n    try:\n        assert ('a' in cache) is True\n    except Exception as e:\n        pytest.fail(f\"'a' in cache raised {type(e).__name__}: {e}\")\n\n    # expiry must still work at original time\n    timer.t = 4\n    assert 'a' in cache\n    assert cache['a'] == 1\n    timer.t = 6\n    assert 'a' not in cache\n\n\ndef test_overwrite_arithmetic_preserves_order_and_value():\n    cache = TTLCache(maxsize=3, ttl=10, timer=lambda: 0)\n    cache['a'] = 1\n    cache['b'] = 2\n    cache['c'] = 3\n    before_list = list(cache)  # ['a','b','c']\n    before_dict = dict(cache)\n    old_expires = cache._TTLCache__links['a'].expires\n\n    cache._TTLCache__ttl = BadOverflow()\n    with pytest.raises(OverflowError):\n        cache['a'] = 99\n\n    # overwriting should be atomic: no move-to-end, value unchanged\n    assert list(cache) == before_list\n    assert dict(cache) == before_dict\n    assert len(cache) == 3\n    assert cache.currsize == 3\n    assert cache['a'] == 1\n    assert cache._TTLCache__links['a'].expires == old_expires\n    try:\n        assert ('a' in cache) is True\n    except Exception as e:\n        pytest.fail(f\"'a' in cache raised {type(e).__name__}: {e}\")\n",
