      "test": "import pytest\nfrom jinja2 import Environment\n\n\n@pytest.fixture\ndef env():\n    return Environment()\n\n\n# Characters that end an attribute name in the HTML spec Attribute name state:\n# TAB \\t, LF \\n, FF \\f, CR \\r, SPACE, \"/\" , \">\" , \"=\"\nINVALID_KEYS = [\n    \"a/b\",          # SOLIDUS /\n    \"a>b\",          # GREATER-THAN SIGN >\n    \"a b\",          # SPACE\n    \"a=b\",          # EQUALS SIGN =\n    \"a\\tb\",         # TAB\n    \"a\\nb\",         # LF\n    \"a\\rb\",         # CR\n    \"a\\fb\",         # FF\n    \"src=1 onerror=alert(1)\",  # example from bug report\n]\n\n# Ordinary names that must keep working, including -, :, ., _, digits, non-ASCII\nVALID_KEYS = [\n    \"foo\",\n    \"data-foo\",\n    \"xml:lang\",\n    \"a.b\",\n    \"a_b\",\n    \"a1\",\n    \"a-1:b.c_d\",\n    \"\u00e9\u00e0\u00fc\",\n    \"caf\u00e9\",\n    \"foo:bar-baz.qux_123\",\n]\n\n\n@pytest.mark.parametrize(\"bad_key\", INVALID_KEYS)\ndef test_xmlattr_rejects_invalid_keys_literal(env, bad_key):\n    # only test keys that can be written as a literal without breaking Jinja parsing\n    # \"/\" and \">\" and \"=\" and space are safe to write literally; whitespace controls are tested via variable\n    if any(c in bad_key for c in \"\\t\\n\\r\\f\"):\n        pytest.skip(\"whitespace control tested via variable dict\")\n    tmpl_src = \"{{ {\" + repr(bad_key) + \": '1'}|xmlattr }}\"\n    with pytest.raises(ValueError):\n        env.from_string(tmpl_src).render()\n\n\n@pytest.mark.parametrize(\"bad_key\", INVALID_KEYS)\ndef test_xmlattr_rejects_invalid_keys_variable_dict(env, bad_key):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ attrs|xmlattr }}\").render(attrs={bad_key: \"1\"})\n\n\n@pytest.mark.parametrize(\"bad_key\", INVALID_KEYS)\ndef test_xmlattr_rejects_invalid_keys_variable_key(env, bad_key):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {key: '1'}|xmlattr }}\").render(key=bad_key)\n\n\n@pytest.mark.parametrize(\"bad_key\", [\"/\", \">\", \"\\t\", \"\\n\", \"\\r\", \"\\f\"])\ndef test_xmlattr_rejects_single_terminator_as_key(env, bad_key):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ attrs|xmlattr }}\").render(attrs={f\"a{bad_key}b\": \"1\"})\n\n\ndef test_xmlattr_valid_names_still_work_literal(env):\n    tmpl = env.from_string(\n        \"{{ {'foo': '1', 'data-foo': '2', 'xml:lang': 'en', 'a.b': '3', 'a_b': '4', 'a1': '5', '\u00e9\u00e0\u00fc': '6'}|xmlattr }}\"\n    )\n    out = tmpl.render()\n    assert 'foo=\"1\"' in out\n    assert 'data-foo=\"2\"' in out\n    assert 'xml:lang=\"en\"' in out\n    assert 'a.b=\"3\"' in out\n    assert 'a_b=\"4\"' in out\n    assert 'a1=\"5\"' in out\n    assert '\u00e9\u00e0\u00fc=\"6\"' in out\n\n\n@pytest.mark.parametrize(\"good_key\", VALID_KEYS)\ndef test_xmlattr_valid_keys_via_variable(env, good_key):\n    out = env.from_string(\"{{ attrs|xmlattr }}\").render(attrs={good_key: \"v\"})\n    assert f'{good_key}=\"v\"' in out\n\n\n@pytest.mark.parametrize(\"good_key\", VALID_KEYS)\ndef test_xmlattr_valid_keys_via_variable_key(env, good_key):\n    out = env.from_string(\"{{ {key: 'v'}|xmlattr }}\").render(key=good_key)\n    assert f'{good_key}=\"v\"' in out\n\n\ndef test_xmlattr_escaping_and_none_still_work(env):\n    # values still escaped, none/undefined skipped, autospace default\n    tmpl = env.from_string(\"{{ {'a': '<&>', 'b': none}|xmlattr }}\")\n    out = tmpl.render()\n    assert out.startswith(\" \")\n    assert 'a=\"&lt;&amp;&gt;\"' in out\n    assert \"b=\" not in out\n",
