      "test": "import pytest\nfrom jinja2 import Environment\n\n\n@pytest.fixture\ndef env():\n    return Environment()\n\n\n# Requirement 1: any key containing a char that ends an attribute name\n# must raise ValueError. The buggy code only checks ` \" \" in key and \"=\" in key`,\n# so single-terminator keys bypass it.\n\n@pytest.mark.parametrize(\"key\", [\n    \"a=b\",          # '=' alone\n    \"a b\",          # space alone\n    \"a/b\",          # '/' alone\n    \"a>b\",          # '>' alone\n    \"a\\tb\",         # tab\n    \"a\\nb\",         # newline\n    \"a\\rb\",         # carriage return\n    \"a\\fb\",         # form feed\n    \"a b c\",        # multiple spaces\n    \"=a\",\n    \"a=\",\n    \"/a\",\n    \"a/\",\n    \">a\",\n    \" a\",\n    \"a \",\n])\ndef test_invalid_key_via_dict_variable_raises(env, key):\n    # dict passed as variable\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"1\"})\n\n\ndef test_invalid_key_equals_alone_literal(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a=b': '1'}|xmlattr }}\").render()\n\n\ndef test_invalid_key_space_alone_literal(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a b': '1'}|xmlattr }}\").render()\n\n\ndef test_invalid_key_slash_literal(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a/b': '1'}|xmlattr }}\").render()\n\n\ndef test_invalid_key_gt_literal(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a>b': '1'}|xmlattr }}\").render()\n\n\ndef test_invalid_key_via_key_variable(env):\n    # key passed as variable: {k: 'v'}\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=\"a=b\")\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=\"a b\")\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=\"a/b\")\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=\"a>b\")\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=\"a\\tb\")\n\n\n# Requirement 3: ordinary names keep working\n@pytest.mark.parametrize(\"key\", [\n    \"foo\",\n    \"foo-bar\",\n    \"foo:bar\",\n    \"blub:blub\",\n    \"foo.bar\",\n    \"foo_bar\",\n    \"foo1\",\n    \"a-1:b.c_d\",\n    \"data-foo\",\n    \"caf\u00e9\",\n    \"na\u00efve\",\n    \"\u00fcber\",\n])\ndef test_valid_keys_still_work(env, key):\n    out = env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"1\"})\n    assert f'{key}=\"1\"' in out\n\n\ndef test_valid_keys_literal(env):\n    tmpl = env.from_string(\n        \"{{ {'foo': 42, 'bar': 23, 'fish': none, \"\n        \"'spam': missing, 'blub:blub': '<?>'}|xmlattr }}\"\n    )\n    out = tmpl.render().split()\n    assert len(out) == 3\n    assert 'foo=\"42\"' in out\n    assert 'bar=\"23\"' in out\n    assert 'blub:blub=\"&lt;?&gt;\"' in out\n\n\n# Requirement 4: everything else unchanged\ndef test_values_escaped(env):\n    out = env.from_string(\"{{ {'x': v}|xmlattr }}\").render(v=\"<\\\"&'>\")\n    assert \"&lt;\" in out\n    assert \"&amp;\" in out\n\n\ndef test_none_and_undefined_skipped(env):\n    out = env.from_string(\"{{ {'a': '1', 'b': none, 'c': missing}|xmlattr }}\").render()\n    assert 'a=\"1\"' in out\n    assert 'b=' not in out\n    assert 'c=' not in out\n\n\ndef test_autospace_true_and_false(env):\n    out1 = env.from_string(\"{{ {'foo': 'bar'}|xmlattr }}\").render()\n    assert out1.startswith(\" \")\n    assert 'foo=\"bar\"' in out1\n\n    out2 = env.from_string(\"{{ {'foo': 'bar'}|xmlattr(false) }}\").render()\n    assert not out2.startswith(\" \")\n    assert out2 == 'foo=\"bar\"'\n",
