      "test": "import pytest\nfrom jinja2 import Environment\n\n\n@pytest.fixture\ndef env():\n    return Environment()\n\n\n# Characters that end an attribute name in HTML tokenizer's attribute-name state:\n# whitespace (space, \\t, \\n, \\f, \\r), \"/\", \">\", \"=\"\nINVALID_KEYS = [\n    \"a b\",                          # space\n    \"a\\tb\",                         # tab\n    \"a\\nb\",                         # LF\n    \"a\\fb\",                         # FF\n    \"a\\rb\",                         # CR\n    \"a/b\",                          # slash\n    \"a>b\",                          # >\n    \"a=b\",                          # single =\n    \"src=1 onerror=alert(1)\",       # space + =\n    \"foo bar\",                      # space generic\n    \"=foo\",\n    \"foo=\",\n    \"/foo\",\n    \">foo\",\n]\n\n\n@pytest.mark.parametrize(\"bad_key\", INVALID_KEYS)\ndef test_xmlattr_rejects_terminator_via_variable_dict(env, bad_key):\n    tmpl = env.from_string(\"{{ d|xmlattr }}\")\n    with pytest.raises(ValueError):\n        tmpl.render(d={bad_key: \"1\"})\n\n\n@pytest.mark.parametrize(\"bad_key\", INVALID_KEYS)\ndef test_xmlattr_rejects_terminator_via_variable_key(env, bad_key):\n    # key passed in as variable: {{ {k: '1'}|xmlattr }}\n    tmpl = env.from_string(\"{{ {k: '1'}|xmlattr }}\")\n    with pytest.raises(ValueError):\n        tmpl.render(k=bad_key)\n\n\n# Literal dict cases (including the example from the bug report)\n@pytest.mark.parametrize(\"bad_key\", [\"a b\", \"a=b\", \"a/b\", \"a>b\", \"src=1 onerror=alert(1)\"])\ndef test_xmlattr_rejects_terminator_via_literal_dict(env, bad_key):\n    # Build template with literal key using repr to keep Jinja syntax valid\n    tmpl_src = \"{{ {\" + repr(bad_key) + \": '1'}|xmlattr }}\"\n    tmpl = env.from_string(tmpl_src)\n    with pytest.raises(ValueError):\n        tmpl.render()\n\n\ndef test_xmlattr_literal_example_from_report(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'src=1 onerror=alert(1)': 'my_class'}|xmlattr }}\").render()\n\n\ndef test_xmlattr_space_specific_counterexample(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={\"a b\": \"1\"})\n\n\ndef test_xmlattr_single_equals_counterexample(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={\"a=b\": \"x\"})\n\n\n# Ordinary attribute names must keep working (Requirement 3)\nVALID_KEYS = [\n    \"foo\",\n    \"foo-bar\",\n    \"foo:bar\",\n    \"foo.bar\",\n    \"foo_bar\",\n    \"foo1\",\n    \"data-value\",\n    \"xml:lang\",\n    \"_private\",\n    \"a-b_c:d.e\",\n    \"caf\u00e9\",          # non-ASCII\n    \"na\u00efve\",\n    \"\u00dcnicode\",\n]\n\n@pytest.mark.parametrize(\"good_key\", VALID_KEYS)\ndef test_xmlattr_valid_names_still_work(env, good_key):\n    tmpl = env.from_string(\"{{ d|xmlattr }}\")\n    out = tmpl.render(d={good_key: \"1\"})\n    # should not raise and should contain key=\"1\"\n    assert f'{good_key}=\"1\"' in out\n\n\ndef test_xmlattr_valid_names_literal(env):\n    tmpl = env.from_string(\n        \"{{ {'foo-bar': 'a', 'foo:bar': 'b', 'foo.bar': 'c', 'foo_bar': 'd', 'a1': 'e'}|xmlattr }}\"\n    )\n    out = tmpl.render()\n    assert 'foo-bar=\"a\"' in out\n    assert 'foo:bar=\"b\"' in out\n    assert 'foo.bar=\"c\"' in out\n    assert 'foo_bar=\"d\"' in out\n    assert 'a1=\"e\"' in out\n\n\n# Requirement 4: everything else unchanged\ndef test_xmlattr_values_still_escaped(env):\n    tmpl = env.from_string(\"{{ {'foo': '<>&\\\"'}|xmlattr }}\")\n    out = tmpl.render()\n    assert 'foo=\"&lt;&gt;&amp;&#34;\"' in out or 'foo=\"&lt;&gt;&amp;&quot;\"' in out\n\n\ndef test_xmlattr_none_and_undefined_skipped(env):\n    tmpl = env.from_string(\"{{ {'foo': none, 'bar': 'baz', 'qux': missing}|xmlattr }}\")\n    out = tmpl.render()\n    assert 'foo=' not in out\n    assert 'qux=' not in out\n    assert 'bar=\"baz\"' in out\n\n\ndef test_xmlattr_autospace(env):\n    tmpl = env.from_string(\"{{ {'foo': 'bar'}|xmlattr }}\")\n    assert tmpl.render() == ' foo=\"bar\"'\n    tmpl2 = env.from_string(\"{{ {'foo': 'bar'}|xmlattr(false) }}\")\n    assert tmpl2.render() == 'foo=\"bar\"'\n",
