      "test": "import pytest\nfrom jinja2 import Environment\n\n\n@pytest.fixture\ndef env():\n    return Environment()\n\n\n# Requirement 1: any character that ends attribute name state must raise\n# HTML spec attribute-name-state terminators: space, \\t, \\n, \\f, \\r, \"/\", \">\", \"=\"\nBAD_KEYS = [\n    \"a b\",      # space\n    \"a\\tb\",     # tab \\x09\n    \"a\\nb\",     # lf \\x0a\n    \"a\\fb\",     # form feed \\x0c\n    \"a\\rb\",     # carriage return \\x0d\n    \"a=b\",      # equals\n    \"a/b\",      # slash\n    \"a>b\",      # greater than\n    \"src=1 onerror=alert(1)\",  # example from report (both '=' and space)\n]\n\n\n# Requirement 3: these must keep working\nVALID_DICT = {\n    \"data-foo\": \"1\",\n    \"foo:bar\": \"2\",\n    \"a.b\": \"3\",\n    \"foo_bar\": \"4\",\n    \"a1\": \"5\",\n    \"a-1:b.c_d\": \"6\",\n    \"caf\u00e9\": \"7\",\n    \"na\u00efve\": \"8\",\n}\n\n\ndef test_literal_rejects_space(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a b': 'x'}|xmlattr }}\").render()\n\n\ndef test_literal_rejects_equals(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a=b': 'x'}|xmlattr }}\").render()\n\n\ndef test_literal_rejects_slash(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a/b': 'x'}|xmlattr }}\").render()\n\n\ndef test_literal_rejects_gt(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a>b': 'x'}|xmlattr }}\").render()\n\n\n@pytest.mark.parametrize(\"bad\", BAD_KEYS)\ndef test_dict_variable_rejects_terminators(env, bad):\n    # Requirement 2: dicts passed in as variables must be checked\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={bad: \"x\"})\n\n\n@pytest.mark.parametrize(\"bad\", BAD_KEYS)\ndef test_key_variable_rejects_terminators(env, bad):\n    # Requirement 2: keys passed in as variables must be checked\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: 'x'}|xmlattr }}\").render(k=bad)\n\n\n@pytest.mark.parametrize(\"bad\", [\"a b\", \"a=b\", \"a/b\", \"a>b\"])\ndef test_literal_parametrized_rejects(env, bad):\n    # literal dicts in template\n    tmpl = \"{{ {'%s': 'x'}|xmlattr }}\" % bad\n    with pytest.raises(ValueError):\n        env.from_string(tmpl).render()\n\n\ndef test_valid_names_literal_still_work(env):\n    tmpl = env.from_string(\"{{ {'foo-bar': '1', 'foo:bar': '2', 'foo.bar': '3', 'foo_bar': '4', 'a1': '5', 'caf\\u00e9': '6'}|xmlattr }}\")\n    out = tmpl.render()\n    assert 'foo-bar=\"1\"' in out\n    assert 'foo:bar=\"2\"' in out\n    assert 'foo.bar=\"3\"' in out\n    assert 'foo_bar=\"4\"' in out\n    assert 'a1=\"5\"' in out\n    assert 'caf\\u00e9=\"6\"' in out or 'caf\u00e9=\"6\"' in out\n\n\ndef test_valid_names_via_variable_still_work(env):\n    out = env.from_string(\"{{ d|xmlattr }}\").render(d=VALID_DICT)\n    for k, v in VALID_DICT.items():\n        assert f'{k}=\"{v}\"' in out\n\n\ndef test_valid_names_via_key_variable_still_work(env):\n    for k, v in VALID_DICT.items():\n        out = env.from_string(\"{{ {k: v}|xmlattr }}\").render(k=k, v=v)\n        assert f'{k}=\"{v}\"' in out\n\n\ndef test_xmlattr_escaping_autospace_none_still_work(env):\n    # Requirement 4: everything else unchanged\n    tmpl = env.from_string(\"{{ {'blub:blub': '<?>'}|xmlattr }}\")\n    out = tmpl.render()\n    assert 'blub:blub=\"&lt;?&gt;\"' in out\n    # autospace prepends space\n    assert out.startswith(\" \")\n    # autospace=false\n    out2 = env.from_string(\"{{ {'foo': 'bar'}|xmlattr(false) }}\").render()\n    assert out2 == 'foo=\"bar\"'\n    # none / undefined skipped\n    out3 = env.from_string(\"{{ {'a': none, 'b': '2'}|xmlattr }}\").render()\n    assert 'a=' not in out3\n    assert 'b=\"2\"' in out3\n",
