      "status": "confirmed",
      "test": "import pytest\nfrom jinja2 import Environment\n\n\n@pytest.fixture\ndef env():\n    return Environment()\n\n\n# Keys that contain a character that ends an attribute name in the HTML\n# tokenizer's attribute-name state: space, \\t, \\n, \\f, \\r, \"/\", \">\", \"=\"\n# Each of those must cause ValueError. The buggy code only checks for\n# on* handler pattern and therefore lets these through.\nINVALID_KEYS = [\n    \"a b\",          # space\n    \"a\\tb\",         # tab\n    \"a\\nb\",         # lf\n    \"a\\rb\",         # cr\n    \"a\\fb\",         # ff  (\\x0c)\n    \"a/b\",          # slash\n    \"a>b\",          # >\n    \"a=b\",          # =\n]\n\n# Subset that can be written as a literal dict key in a Jinja template\n# without needing Python escapes inside the template source.\nLITERAL_INVALID_KEYS = [\n    \"a b\",\n    \"a/b\",\n    \"a>b\",\n    \"a=b\",\n]\n\n\n@pytest.mark.parametrize(\"key\", LITERAL_INVALID_KEYS)\ndef test_xmlattr_rejects_invalid_key_literal_dict(env, key):\n    # literal dict in template\n    tmpl = \"{{ {\" + repr(key) + \": 'x'}|xmlattr }}\"\n    with pytest.raises(ValueError):\n        env.from_string(tmpl).render()\n\n\n@pytest.mark.parametrize(\"key\", INVALID_KEYS)\ndef test_xmlattr_rejects_invalid_key_via_variable_dict(env, key):\n    # dict passed in as variable\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"x\"})\n\n\n@pytest.mark.parametrize(\"key\", INVALID_KEYS)\ndef test_xmlattr_rejects_invalid_key_via_variable_key(env, key):\n    # key passed in as variable -> {(k): ...}\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {(k): 'x'}|xmlattr }}\").render(k=key)\n\n\ndef test_xmlattr_rejects_all_terminators_together(env):\n    # sanity: each terminator char alone as part of key must be rejected\n    for ch in [\" \", \"\\t\", \"\\n\", \"\\r\", \"\\x0c\", \"/\", \">\", \"=\"]:\n        bad = f\"a{ch}b\"\n        with pytest.raises(ValueError):\n            env.from_string(\"{{ d|xmlattr }}\").render(d={bad: \"1\"})\n\n\ndef test_xmlattr_valid_names_still_work(env):\n    # requirement 3: -, :, ., _, digits and non-ASCII keep working\n    d = {\n        \"data-value\": \"1\",\n        \"xml:lang\": \"2\",\n        \"a.b\": \"3\",\n        \"a_b\": \"4\",\n        \"a2\": \"5\",\n        \"caf\u00e9\": \"6\",\n        \"foo-bar:baz.qux_123\": \"7\",\n    }\n    out = env.from_string(\"{{ d|xmlattr }}\").render(d=d)\n    # should not raise and must contain all attributes escaped\n    for k, v in d.items():\n        assert f'{k}=\"{v}\"' in out\n\n    # also via literal dict including colon (original test style)\n    tmpl = env.from_string(\n        \"{{ {'foo': 42, 'bar': 23, 'blub:blub': '<?>'}|xmlattr }}\"\n    )\n    out2 = tmpl.render().split()\n    assert 'foo=\"42\"' in out2\n    assert 'bar=\"23\"' in out2\n    assert 'blub:blub=\"&lt;?&gt;\"' in out2\n\n\ndef test_xmlattr_values_escaped_and_none_skipped(env):\n    # values still escaped, none/undefined skipped, autospace unchanged\n    tmpl = env.from_string(\"{{ {'a': '<&>', 'b': none, 'c': 'x'}|xmlattr }}\")\n    out = tmpl.render()\n    assert 'a=\"&lt;&amp;&gt;\"' in out\n    assert 'c=\"x\"' in out\n    assert 'b=' not in out\n    assert out.startswith(\" \")\n\n    tmpl2 = env.from_string(\"{{ {'a': '1'}|xmlattr(false) }}\")\n    out2 = tmpl2.render()\n    assert out2 == 'a=\"1\"'\n    assert not out2.startswith(\" \")\n",
