      "test": "import pytest\nfrom jinja2 import Environment\nfrom markupsafe import Markup\n\n\n@pytest.mark.parametrize(\"key\", [\n    \"a b\",\n    \"a\\tb\",\n    \"a\\nb\",\n    \"a\\rb\",\n    \"a\\fb\",\n    \"a/b\",\n    \"a>b\",\n    \"a=b\",\n])\ndef test_xmlattr_invalid_key_via_variable_dict_raises(key):\n    env = Environment()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"1\"})\n\n\n@pytest.mark.parametrize(\"key\", [\n    \"a b\",\n    \"a/b\",\n    \"a>b\",\n    \"a=b\",\n])\ndef test_xmlattr_invalid_literal_dict_raises(key):\n    # literal dict in template, using variable to avoid quoting issues for controls\n    # but also test simple literals directly\n    env = Environment()\n    # build template string with repr to safely embed key\n    tmpl = \"{{ {\" + repr(key) + \": '1'}|xmlattr }}\"\n    with pytest.raises(ValueError):\n        env.from_string(tmpl).render()\n\n\ndef test_xmlattr_invalid_key_via_key_variable_raises():\n    env = Environment()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=\"a b\")\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=\"a/b\")\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=\"a>b\")\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=\"a=b\")\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=\"a\\tb\")\n\n\n@pytest.mark.parametrize(\"key\", [\n    \"foo\",\n    \"data-value\",\n    \"aria:pressed\",\n    \"my.attr\",\n    \"my_attr\",\n    \"a1\",\n    \"foo:bar-baz.qux_123\",\n    \"caf\u00e9\",\n    \"na\u00efve\",\n    \"_private\",\n    \"XML:lang\",\n])\ndef test_xmlattr_valid_keys_still_work(key):\n    env = Environment()\n    out = env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"v\"})\n    # should not raise and should contain the attribute\n    assert f'{key}=\"v\"' in out\n    # also via literal\n    out2 = env.from_string(\"{{ {\" + repr(key) + \": 'v'}|xmlattr }}\").render()\n    assert f'{key}=\"v\"' in out2\n\n\ndef test_xmlattr_other_behavior_unchanged():\n    env = Environment()\n    # none and undefined are skipped\n    out = env.from_string(\n        \"{{ {'foo': 42, 'bar': 23, 'fish': none, 'spam': missing, 'blub:blub': '<?>'}|xmlattr }}\"\n    ).render().split()\n    assert len(out) == 3\n    assert 'foo=\"42\"' in out\n    assert 'bar=\"23\"' in out\n    assert 'blub:blub=\"&lt;?&gt;\"' in out\n\n    # values are escaped\n    out = env.from_string(\"{{ {'k': '<&\\\"'}|xmlattr }}\").render()\n    assert \"&lt;\" in out\n    assert \"&amp;\" in out\n    assert \"&quot;\" in out or \"&#34;\" in out\n\n    # autospace\n    assert env.from_string(\"{{ {'a': 1}|xmlattr }}\").render() == ' a=\"1\"'\n    assert env.from_string(\"{{ {'a': 1}|xmlattr(false) }}\").render() == 'a=\"1\"'\n    assert env.from_string(\"{{ d|xmlattr }}\").render(d={}) == \"\"\n    assert env.from_string(\"{{ d|xmlattr(false) }}\").render(d={}) == \"\"\n\n    # autoescape returns Markup\n    env2 = Environment(autoescape=True)\n    out = env2.from_string(\"{{ {'a': 1}|xmlattr }}\").render()\n    assert isinstance(out, Markup)\n    assert 'a=\"1\"' in out\n\n    # valid keys with allowed punctuation still allowed with autospace false\n    out = env.from_string(\"{{ {'data-foo': 1, 'x:y': 2}|xmlattr(false) }}\").render()\n    assert 'data-foo=\"1\"' in out\n    assert 'x:y=\"2\"' in out\n",
