      "status": "confirmed",
      "test": "import pytest\nfrom jinja2 import Environment\n\n# Characters that end an attribute name in HTML tokenizer's attribute-name state\n# https://html.spec.whatwg.org/#attribute-name-state\nBAD_CHARS = [\" \", \"\\t\", \"\\n\", \"\\f\", \"\\r\", \"/\", \">\", \"=\"]\n\nVALID_NAMES = [\n    \"foo\",\n    \"data-value\",\n    \"data:value\",\n    \"data.value\",\n    \"data_value\",\n    \"attr1\",\n    \"a1b2\",\n    \"caf\u00e9\",\n    \"na\u00efve\",\n    \"\u00dcnicode\",\n    \"blub:blub\",\n    \"my-attr_1.test:ok\",\n]\n\ndef _env():\n    return Environment()\n\n# Requirement 1: any single terminator must raise ValueError\n\n@pytest.mark.parametrize(\"ch\", BAD_CHARS)\ndef test_single_bad_char_via_variable_dict(ch):\n    env = _env()\n    d = {f\"a{ch}b\": \"x\"}\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d=d)\n\n@pytest.mark.parametrize(\"ch\", BAD_CHARS)\ndef test_single_bad_char_via_key_variable(ch):\n    env = _env()\n    k = f\"a{ch}b\"\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: 'x'}|xmlattr }}\").render(k=k)\n\ndef test_single_bad_char_literal_equals():\n    env = _env()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a=b': 'x'}|xmlattr }}\").render()\n\ndef test_single_bad_char_literal_space():\n    env = _env()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a b': 'x'}|xmlattr }}\").render()\n\ndef test_single_bad_char_literal_slash():\n    env = _env()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a/b': 'x'}|xmlattr }}\").render()\n\ndef test_single_bad_char_literal_gt():\n    env = _env()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a>b': 'x'}|xmlattr }}\").render()\n\ndef test_single_bad_char_only_one_delimiter_cases():\n    env = _env()\n    # cases that have exactly one bad character \u2013 the buggy code allows n_bad==1\n    for key in [\"a=b\", \"a b\", \"a/b\", \"a>b\", \"a\\tb\", \"a\\nb\", \"a\\fb\", \"a\\rb\"]:\n        with pytest.raises(ValueError):\n            env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"x\"})\n\n# Requirement 2: holds however filter is reached \u2013 also literal with two delimiters\ndef test_literal_still_raises_with_two_delimiters():\n    env = _env()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'src=1 onerror=alert(1)': 'x'}|xmlattr }}\").render()\n\n# Requirement 3: ordinary names keep working\n@pytest.mark.parametrize(\"name\", VALID_NAMES)\ndef test_valid_names_keep_working_literal(name):\n    env = _env()\n    out = env.from_string(\"{{ {k: 'v'}|xmlattr }}\").render(k=name)\n    assert f'{name}=\"v\"' in out\n\n@pytest.mark.parametrize(\"name\", VALID_NAMES)\ndef test_valid_names_keep_working_variable_dict(name):\n    env = _env()\n    out = env.from_string(\"{{ d|xmlattr }}\").render(d={name: \"1\"})\n    assert f'{name}=\"1\"' in out\n\ndef test_valid_names_with_digits_and_non_ascii():\n    env = _env()\n    tmpl = env.from_string(\"{{ {'foo-1': 1, 'b:c': 2, 'd.e': 3, 'x_y': 4, 'caf\u00e9': 5}|xmlattr }}\")\n    out = tmpl.render()\n    assert 'foo-1=\"1\"' in out\n    assert 'b:c=\"2\"' in out\n    assert 'd.e=\"3\"' in out\n    assert 'x_y=\"4\"' in out\n    assert 'caf\u00e9=\"5\"' in out\n\n# Requirement 4: everything else unchanged\ndef test_none_and_undefined_skipped():\n    env = _env()\n    out = env.from_string(\"{{ {'a': none, 'b': missing, 'c': 'ok'}|xmlattr }}\").render()\n    assert 'c=\"ok\"' in out\n    assert 'a=' not in out\n    assert 'b=' not in out\n\ndef test_values_still_escaped():\n    env = _env()\n    out = env.from_string(\"{{ {'k': '<&>'}|xmlattr }}\").render()\n    assert '&lt;&amp;&gt;' in out\n\ndef test_autospace_behavior():\n    env = _env()\n    t = env.from_string(\"{{ {'a': '1'}|xmlattr }}\")\n    assert t.render() == ' a=\"1\"'\n    t2 = env.from_string(\"{{ {'a': '1'}|xmlattr(false) }}\")\n    assert t2.render() == 'a=\"1\"'\n    t3 = env.from_string(\"{{ {}|xmlattr }}\")\n    assert t3.render() == \"\"\n",
