      "status": "confirmed",
      "test": "import pytest\nimport requests\n\n\ndef test_https_proxy_auth_not_added_for_any_port():\n    # Correct fix: no https URL ever gets Proxy-Authorization,\n    # regardless of proxy port. Buggy code only suppresses port 8090.\n    session = requests.Session()\n    for port in (8000, 8080, 3128, 8888, 9999, 8001):\n        proxies = {\n            \"http\": \"http://test:pass@localhost:8080\",\n            \"https\": f\"http://test:pass@localhost:{port}\",\n        }\n        req = requests.Request(\"GET\", \"https://example.com\")\n        prep = req.prepare()\n        session.rebuild_proxies(prep, proxies)\n        assert \"Proxy-Authorization\" not in prep.headers, f\"leaked for https proxy port {port}\"\n\n    # also without explicit port\n    proxies = {\n        \"http\": \"http://test:pass@localhost:8080\",\n        \"https\": \"http://test:pass@localhost\",\n    }\n    req = requests.Request(\"GET\", \"https://example.com\")\n    prep = req.prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_http_proxy_auth_still_added_for_any_port():\n    # Requirement 3: plain http must still get proxy auth, even on port 8090\n    session = requests.Session()\n    for port in (8000, 8080, 8090, 3128, 9999):\n        proxies = {\n            \"http\": f\"http://test:pass@localhost:{port}\",\n            \"https\": \"http://test:pass@localhost:8090\",\n        }\n        req = requests.Request(\"GET\", \"http://example.com\")\n        prep = req.prepare()\n        session.rebuild_proxies(prep, proxies)\n        assert \"Proxy-Authorization\" in prep.headers, f\"missing for http proxy port {port}\"\n\n    # without explicit port\n    proxies = {\n        \"http\": \"http://test:pass@localhost\",\n        \"https\": \"http://test:pass@localhost:8090\",\n    }\n    req = requests.Request(\"GET\", \"http://example.com\")\n    prep = req.prepare()\n    session.rebuild_proxies(prep, proxies)\n    assert \"Proxy-Authorization\" in prep.headers\n\n\ndef test_https_env_proxy_never_has_proxy_auth(monkeypatch):\n    # Requirement 1: env HTTPS_PROXY must not leak to https URL\n    monkeypatch.setenv(\"HTTPS_PROXY\", \"http://envuser:envpass@proxy.example:8000\")\n    monkeypatch.setenv(\"https_proxy\", \"http://envuser:envpass@proxy.example:8000\")\n    monkeypatch.delenv(\"NO_PROXY\", raising=False)\n    monkeypatch.delenv(\"no_proxy\", raising=False)\n    monkeypatch.delenv(\"HTTP_PROXY\", raising=False)\n    monkeypatch.delenv(\"http_proxy\", raising=False)\n\n    session = requests.Session()\n    session.trust_env = True\n    req = requests.Request(\"GET\", \"https://example.com\")\n    prep = req.prepare()\n    session.rebuild_proxies(prep, {})\n    assert \"Proxy-Authorization\" not in prep.headers\n\n\ndef test_http_env_proxy_still_has_proxy_auth(monkeypatch):\n    monkeypatch.setenv(\"HTTP_PROXY\", \"http://envuser:envpass@proxy.example:8000\")\n    monkeypatch.setenv(\"http_proxy\", \"http://envuser:envpass@proxy.example:8000\")\n    monkeypatch.delenv(\"NO_PROXY\", raising=False)\n    monkeypatch.delenv(\"no_proxy\", raising=False)\n    monkeypatch.delenv(\"HTTPS_PROXY\", raising=False)\n    monkeypatch.delenv(\"https_proxy\", raising=False)\n\n    session = requests.Session()\n    session.trust_env = True\n    req = requests.Request(\"GET\", \"http://example.com\")\n    prep = req.prepare()\n    session.rebuild_proxies(prep, {})\n    assert \"Proxy-Authorization\" in prep.headers\n\n\ndef test_redirect_http_to_https_does_not_leak_proxy_auth():\n    # Requirement 2: redirect from http -> https must not carry header\n    session = requests.Session()\n    proxies = {\n        \"http\": \"http://test:pass@localhost:8080\",\n        \"https\": \"http://test:pass@localhost:8000\",  # not 8090 -> buggy leaks\n    }\n    # initial http request gets proxy auth\n    req_http = requests.Request(\"GET\", \"http://example.com\")\n    prep_http = req_http.prepare()\n    session.rebuild_proxies(prep_http, proxies)\n    assert \"Proxy-Authorization\" in prep_http.headers\n\n    # simulate redirect: copy prepared request (as resolve_redirects does) and change URL to https\n    # the previous header would still be present if not stripped\n    req_https = requests.Request(\"GET\", \"https://example.com/\")\n    prep_https = req_https.prepare()\n    # simulate leak: attacker would have previous Proxy-Authorization still in headers\n    prep_https.headers[\"Proxy-Authorization\"] = prep_http.headers[\"Proxy-Authorization\"]\n    session.rebuild_proxies(prep_https, proxies)\n    assert \"Proxy-Authorization\" not in prep_https.headers\n\n\ndef test_redirect_https_to_http_keeps_proxy_auth():\n    # Requirement 3: redirect to http (even from https) must still authenticate to proxy\n    session = requests.Session()\n    proxies = {\n        \"http\": \"http://test:pass@localhost:8080\",\n        \"https\": \"http://test:pass@localhost:8000\",\n    }\n    req_https = requests.Request(\"GET\", \"https://example.com\")\n    prep_https = req_https.prepare()\n    session.rebuild_proxies(prep_https, proxies)\n    assert \"Proxy-Authorization\" not in prep_https.headers\n\n    req_http = requests.Request(\"GET\", \"http://example.com/\")\n    prep_http = req_http.prepare()\n    session.rebuild_proxies(prep_http, proxies)\n    assert \"Proxy-Authorization\" in prep_http.headers\n\n    # also when proxy uses port 8090, http must still get it (buggy suppresses)\n    proxies2 = {\n        \"http\": \"http://test:pass@localhost:8090\",\n        \"https\": \"http://test:pass@localhost:8090\",\n    }\n    req_http2 = requests.Request(\"GET\", \"http://example.com/\")\n    prep_http2 = req_http2.prepare()\n    session.rebuild_proxies(prep_http2, proxies2)\n    assert \"Proxy-Authorization\" in prep_http2.headers\n",
