      "status": "confirmed",
      "test": "import pytest\nfrom cachetools import TTLCache\nfrom datetime import datetime, timedelta\n\nclass FailTime:\n    def __init__(self, v):\n        self.v = v\n    def __add__(self, other):\n        raise RuntimeError(\"expiration failed\")\n    __radd__ = __add__\n    def __lt__(self, other):\n        return self.v < other\n    def __le__(self, other):\n        return self.v <= other\n    def __gt__(self, other):\n        return self.v > other\n    def __ge__(self, other):\n        return self.v >= other\n\n\nclass Timer:\n    def __init__(self):\n        self.time = 0\n        self._fail = False\n    def __call__(self):\n        if self._fail:\n            self._fail = False\n            return FailTime(self.time)\n        return self.time\n    def fail_next(self):\n        self._fail = True\n\n\ndef test_overwrite_failure_is_atomic():\n    # counterexample from review: overwriting existing key must preserve it\n    timer = Timer()\n    cache = TTLCache(maxsize=10, ttl=10, timer=timer)\n    timer.time = 0\n    cache[\"a\"] = 1\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert cache[\"a\"] == 1\n    assert list(cache) == [\"a\"]\n    old_expires = cache._TTLCache__links[\"a\"].expires  # 10\n\n    timer.time = 0\n    timer.fail_next()\n    with pytest.raises(RuntimeError):\n        cache[\"a\"] = 2\n\n    # must be exactly as before, not deleted and not crashed\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    # 'in' must not raise TypeError and must be True\n    assert (\"a\" in cache) is True\n    assert cache[\"a\"] == 1\n    assert list(cache) == [\"a\"]\n    assert cache._TTLCache__links[\"a\"].expires == old_expires\n\n    # expiration time still works behaviourally\n    timer.time = 5\n    assert \"a\" in cache\n    timer.time = 11\n    assert len(cache) == 0\n    assert \"a\" not in cache\n\n\ndef test_overwrite_failure_preserves_order_and_currsize():\n    timer = Timer()\n    cache = TTLCache(maxsize=10, ttl=10, timer=timer)\n    timer.time = 0\n    cache[\"a\"] = 1\n    timer.time = 1\n    cache[\"b\"] = 2\n    timer.time = 2\n    cache[\"c\"] = 3\n    assert list(cache) == [\"a\", \"b\", \"c\"]\n    old_expires_b = cache._TTLCache__links[\"b\"].expires\n    old_currsize = cache.currsize\n\n    timer.time = 5\n    timer.fail_next()\n    with pytest.raises(RuntimeError):\n        cache[\"b\"] = 99\n\n    assert len(cache) == 3\n    assert cache.currsize == old_currsize\n    assert list(cache) == [\"a\", \"b\", \"c\"]  # not [\"a\",\"c\",\"b\"] and not [\"a\",\"c\"]\n    assert cache[\"b\"] == 2\n    assert cache._TTLCache__links[\"b\"].expires == old_expires_b\n    # ensure not broken\n    assert \"b\" in cache\n\n\ndef test_overwrite_failure_preserves_currsize_with_getsizeof():\n    timer = Timer()\n    cache = TTLCache(maxsize=100, ttl=10, timer=timer, getsizeof=len)\n    timer.time = 0\n    cache[\"a\"] = \"x\"\n    assert cache.currsize == 1\n    assert len(cache) == 1\n    timer.time = 1\n    timer.fail_next()\n    with pytest.raises(RuntimeError):\n        cache[\"a\"] = \"xxxxx\"\n    assert cache.currsize == 1\n    assert len(cache) == 1\n    assert cache[\"a\"] == \"x\"\n    assert \"a\" in cache\n    assert list(cache) == [\"a\"]\n\n\ndef test_new_key_failure_leaves_clean():\n    timer = Timer()\n    cache = TTLCache(maxsize=10, ttl=10, timer=timer)\n    timer.time = 0\n    cache[\"a\"] = 1\n    timer.time = 5\n    timer.fail_next()\n    with pytest.raises(RuntimeError):\n        cache[\"b\"] = 2\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert \"b\" not in cache\n    assert \"a\" in cache\n    assert cache[\"a\"] == 1\n    assert list(cache) == [\"a\"]\n\n\ndef test_datetime_overflow_atomic():\n    class DTtimer:\n        def __init__(self):\n            self.time = datetime(2020, 1, 1)\n            self.fail = False\n        def __call__(self):\n            if self.fail:\n                self.fail = False\n                return datetime.max\n            return self.time\n\n    t = DTtimer()\n    cache = TTLCache(maxsize=10, ttl=timedelta(days=1), timer=t)\n    t.time = datetime(2020, 1, 1)\n    cache[\"a\"] = 1\n    old_expires = cache._TTLCache__links[\"a\"].expires\n    t.time = datetime(2020, 1, 2)\n    t.fail = True\n    with pytest.raises(OverflowError):\n        cache[\"a\"] = 2\n    assert len(cache) == 1\n    assert \"a\" in cache\n    assert cache[\"a\"] == 1\n    assert cache._TTLCache__links[\"a\"].expires == old_expires\n\n    t.fail = True\n    with pytest.raises(OverflowError):\n        cache[\"b\"] = 2\n    assert len(cache) == 1\n    assert \"b\" not in cache\n",
