      "status": "confirmed",
      "test": "import pytest\nfrom cachetools import TTLCache\n\n\nclass FlakyTTL:\n    def __init__(self, base):\n        self.base = base\n        self.fail = False\n\n    def __radd__(self, other):\n        if self.fail:\n            raise RuntimeError(\"boom ttl\")\n        return other + self.base\n\n    def __add__(self, other):\n        if self.fail:\n            raise RuntimeError(\"boom ttl\")\n        return self.base + other\n\n\nclass Timer:\n    def __init__(self):\n        self.t = 0\n\n    def __call__(self):\n        return self.t\n\n    def tick(self, n=1):\n        self.t += n\n\n\nclass BadTime:\n    def __add__(self, other):\n        raise OverflowError(\"bad time add\")\n\n    __radd__ = __add__\n\n\nclass FlakyTimer:\n    def __init__(self):\n        self.t = 0\n        self.fail = False\n\n    def __call__(self):\n        if self.fail:\n            return BadTime()\n        return self.t\n\n    def tick(self, n=1):\n        self.t += n\n\n\ndef test_new_key_generic_failure_leaves_cache_intact():\n    timer = Timer()\n    ttl = FlakyTTL(10)\n    cache = TTLCache(maxsize=10, ttl=ttl, timer=timer)\n    cache[\"a\"] = 1\n    cache[\"b\"] = 2\n    # snapshot\n    before_keys = set(cache)\n    before_dict = dict(cache)\n    before_order = list(cache)\n    before_len = len(cache)\n    before_curr = cache.currsize\n\n    ttl.fail = True\n    with pytest.raises(RuntimeError):\n        cache[\"c\"] = 3\n\n    # must not crash with TypeError\n    try:\n        in_c = \"c\" in cache\n    except TypeError:\n        pytest.fail(\"'c' in cache raised TypeError after failed insert\")\n    assert in_c is False\n    try:\n        in_a = \"a\" in cache\n    except TypeError:\n        pytest.fail(\"'a' in cache raised TypeError after failed insert\")\n    assert in_a is True\n\n    assert len(cache) == before_len\n    assert cache.currsize == before_curr\n    assert set(cache) == before_keys\n    assert dict(cache) == before_dict\n    assert list(cache) == before_order\n    assert \"c\" not in cache\n    assert \"c\" not in list(cache)\n    # cache still usable\n    ttl.fail = False\n    cache[\"c\"] = 3\n    assert cache[\"c\"] == 3\n    assert len(cache) == 3\n\n\ndef test_overwrite_generic_failure_leaves_cache_intact():\n    timer = Timer()\n    ttl = FlakyTTL(10)\n    cache = TTLCache(maxsize=10, ttl=ttl, timer=timer)\n    cache[\"k\"] = \"old\"\n    cache[\"x\"] = 1\n    cache[\"y\"] = 2\n    before_dict = dict(cache)\n    before_order = list(cache)\n    before_len = len(cache)\n    before_curr = cache.currsize\n\n    ttl.fail = True\n    with pytest.raises(RuntimeError):\n        cache[\"k\"] = \"new\"\n\n    # value must be restored\n    try:\n        val = cache[\"k\"]\n    except Exception as e:\n        pytest.fail(f\"cache['k'] raised {e!r} after failed overwrite\")\n    assert val == \"old\"\n    assert dict(cache) == before_dict\n    assert list(cache) == before_order\n    assert len(cache) == before_len\n    assert cache.currsize == before_curr\n\n    # expiration time must be preserved: original expires at 10\n    # move time to 5 still present, to 11 expired\n    timer.t = 5\n    assert \"k\" in cache\n    assert cache[\"k\"] == \"old\"\n    timer.t = 11\n    # len and currsize call expire()\n    assert len(cache) == 0\n    assert cache.currsize == 0\n    assert \"k\" not in cache\n    assert list(cache) == []\n\n\ndef test_full_cache_eviction_rollback_on_generic_failure():\n    timer = Timer()\n    ttl = FlakyTTL(10)\n    cache = TTLCache(maxsize=2, ttl=ttl, timer=timer)\n    cache[\"a\"] = 1\n    cache[\"b\"] = 2\n    before_keys = set(cache)\n    before_dict = dict(cache)\n    before_order = list(cache)\n\n    ttl.fail = True\n    with pytest.raises(RuntimeError):\n        cache[\"c\"] = 3\n\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert set(cache) == before_keys\n    assert dict(cache) == before_dict\n    assert list(cache) == before_order\n    try:\n        assert \"c\" not in cache\n        assert \"a\" in cache\n        assert \"b\" in cache\n    except TypeError:\n        pytest.fail(\"contains raised TypeError after failed insert into full cache\")\n\n    ttl.fail = False\n    # now eviction should work normally: inserting c evicts LRU a\n    cache[\"c\"] = 3\n    assert len(cache) == 2\n    assert \"c\" in cache\n\n\ndef test_timer_generic_failure_atomic():\n    timer = FlakyTimer()\n    cache = TTLCache(maxsize=10, ttl=10, timer=timer)\n    cache[\"a\"] = 1\n    cache[\"b\"] = 2\n    before_dict = dict(cache)\n    before_order = list(cache)\n    before_len = len(cache)\n\n    timer.fail = True\n    with pytest.raises(OverflowError):\n        cache[\"c\"] = 3\n\n    try:\n        assert \"c\" not in cache\n    except TypeError:\n        pytest.fail(\"contains raised TypeError after timer failure\")\n\n    assert len(cache) == before_len\n    assert dict(cache) == before_dict\n    assert list(cache) == before_order\n\n    # overwrite with timer failure\n    timer.fail = False\n    cache[\"a\"] = 10  # make sure we can still overwrite normally\n    timer.fail = True\n    before_dict2 = dict(cache)\n    before_order2 = list(cache)\n    with pytest.raises(OverflowError):\n        cache[\"a\"] = 99\n    assert dict(cache) == before_dict2\n    assert list(cache) == before_order2\n    assert cache[\"a\"] == 10\n\n\ndef test_original_exception_propagates_and_cache_usable():\n    timer = Timer()\n    ttl = FlakyTTL(5)\n    cache = TTLCache(maxsize=5, ttl=ttl, timer=timer)\n    cache[\"x\"] = 1\n    ttl.fail = True\n    with pytest.raises(RuntimeError, match=\"boom ttl\"):\n        cache[\"y\"] = 2\n    # cache must still be consistent after exception\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert cache[\"x\"] == 1\n    ttl.fail = False\n    cache[\"y\"] = 2\n    assert cache[\"y\"] == 2\n",
