      "test": "import pytest\nfrom datetime import datetime, timedelta\nfrom cachetools import TTLCache\n\n\ndef test_new_key_overflow_leaves_empty():\n    # datetime.max -1day +2days overflows, guard only checks exact max\n    cache = TTLCache(maxsize=10, ttl=timedelta(days=2), timer=lambda: datetime.max - timedelta(days=1))\n    assert len(cache) == 0\n    assert cache.currsize == 0\n    with pytest.raises(OverflowError):\n        cache[\"k\"] = 1\n    # must be exactly as before\n    assert len(cache) == 0\n    assert cache.currsize == 0\n    assert list(cache) == []\n    # must not crash, must be False\n    assert (\"k\" in cache) is False\n    assert cache.get(\"k\") is None\n    # still usable\n    assert len(cache) == 0\n\ndef test_new_key_typeerror_atomic():\n    cache = TTLCache(maxsize=10, ttl=\"bad\", timer=lambda: 1)\n    with pytest.raises(TypeError):\n        cache[\"k\"] = 1\n    assert len(cache) == 0\n    assert cache.currsize == 0\n    assert list(cache) == []\n    assert (\"k\" in cache) is False\n    assert cache.get(\"k\") is None\n\ndef test_new_key_valueerror_atomic_generic():\n    class BadTTL:\n        def __radd__(self, other):\n            raise ValueError(\"bad ttl\")\n        def __add__(self, other):\n            raise ValueError(\"bad ttl\")\n    cache = TTLCache(maxsize=10, ttl=BadTTL(), timer=lambda: 1)\n    with pytest.raises(ValueError):\n        cache[\"k\"] = 1\n    assert len(cache) == 0\n    assert cache.currsize == 0\n    assert (\"k\" in cache) is False\n    assert list(cache) == []\n\ndef test_overwrite_overflow_preserves_state():\n    # mutable timer to control time\n    t0 = datetime(2020, 1, 1)\n    holder = {\"t\": t0}\n    def timer():\n        return holder[\"t\"]\n    cache = TTLCache(maxsize=10, ttl=timedelta(days=1), timer=timer)\n    cache[\"a\"] = 1\n    cache[\"b\"] = 2\n    assert list(cache) == [\"a\", \"b\"]\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert cache[\"a\"] == 1\n    # now make next computation overflow\n    holder[\"t\"] = datetime.max - timedelta(hours=12)\n    with pytest.raises(OverflowError):\n        cache[\"a\"] = 99  # overwrite should fail atomically\n    # exactly as before\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert list(cache) == [\"a\", \"b\"]\n    assert (\"a\" in cache) is True\n    # value unchanged\n    holder[\"t\"] = datetime(2020, 1, 1, 12, 0, 0)\n    assert cache[\"a\"] == 1\n    assert cache[\"b\"] == 2\n    # expiration time unchanged: a was set at t0 with ttl 1 day -> expires 2020-01-02\n    holder[\"t\"] = datetime(2020, 1, 1, 12, 0, 0)\n    assert \"a\" in cache\n    holder[\"t\"] = datetime(2020, 1, 3, 0, 0, 0)\n    assert \"a\" not in cache\n    assert \"b\" not in cache\n\ndef test_overwrite_typeerror_preserves_iteration_order():\n    holder = {\"t\": 0}\n    def timer():\n        return holder[\"t\"]\n    cache = TTLCache(maxsize=10, ttl=timedelta(seconds=100), timer=timer)\n    cache[\"x\"] = 1\n    cache[\"y\"] = 2\n    cache[\"z\"] = 3\n    assert list(cache) == [\"x\", \"y\", \"z\"]\n    # make ttl bad for next operation only by replacing cache.ttl with bad object\n    # use a new cache with bad ttl but same timer state via monkey patch\n    # simpler: create second cache sharing same timer holder but bad ttl and test overwrite via direct mutation\n    # we test by switching ttl to bad value via private attribute\n    cache._TTLCache__ttl = \"bad\"  # ttl now causes TypeError on time+ttl\n    with pytest.raises(TypeError):\n        cache[\"y\"] = 99\n    # rollback must restore order and values\n    assert len(cache) == 3\n    assert cache.currsize == 3\n    assert list(cache) == [\"x\", \"y\", \"z\"]\n    assert (\"y\" in cache) is True\n    holder[\"t\"] = 0\n    # restore good ttl to check values still accessible\n    cache._TTLCache__ttl = timedelta(seconds=100)\n    assert cache[\"y\"] == 2\n    assert cache[\"x\"] == 1\n\ndef test_failed_insert_does_not_evict_lru():\n    t0 = datetime(2020, 1, 1)\n    holder = {\"t\": t0}\n    def timer():\n        return holder[\"t\"]\n    cache = TTLCache(maxsize=2, ttl=timedelta(days=1), timer=timer)\n    cache[\"a\"] = 1\n    cache[\"b\"] = 2\n    assert len(cache) == 2\n    assert set(cache) == {\"a\", \"b\"}\n    holder[\"t\"] = datetime.max - timedelta(days=1)\n    # ttl 2 days will overflow\n    cache._TTLCache__ttl = timedelta(days=2)\n    with pytest.raises(OverflowError):\n        cache[\"c\"] = 3\n    # no eviction, still a and b\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert set(cache) == {\"a\", \"b\"}\n    assert \"c\" not in cache\n    assert list(cache) == [\"a\", \"b\"]\n    # LRU still works for successful insert\n    holder[\"t\"] = t0\n    cache._TTLCache__ttl = timedelta(days=1)\n    cache[\"c\"] = 3\n    assert len(cache) == 2\n    assert \"a\" not in cache  # evicted LRU\n    assert \"b\" in cache and \"c\" in cache\n\ndef test_failed_insert_keeps_cache_usable():\n    cache = TTLCache(maxsize=10, ttl=timedelta(days=2), timer=lambda: datetime.max - timedelta(days=1))\n    with pytest.raises(OverflowError):\n        cache[\"k\"] = 1\n    assert len(cache) == 0\n    # after failure, a good cache should still work\n    good = TTLCache(maxsize=10, ttl=timedelta(days=1), timer=lambda: datetime(2020, 1, 1))\n    good[\"x\"] = 1\n    assert good[\"x\"] == 1\n    assert len(good) == 1\n",
