      "test": "import pytest\nfrom cachetools import TTLCache\n\n\nclass Timer:\n    def __init__(self, t=0):\n        self.time = t\n\n    def __call__(self):\n        return self.time\n\n\nclass FailTTL:\n    def __init__(self, fail_on=None):\n        self.fail_on = fail_on\n\n    def __radd__(self, other):\n        if self.fail_on is not None and other == self.fail_on:\n            raise RuntimeError(\"boom\")\n        return other + 10\n\n    __add__ = __radd__\n\n\ndef test_new_key_generic_failure_atomic():\n    timer = Timer(0)\n    ttl = FailTTL(fail_on=1)\n    cache = TTLCache(maxsize=10, ttl=ttl, timer=timer)\n\n    timer.time = 0\n    cache[\"a\"] = 1\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert list(cache) == [\"a\"]\n    assert cache[\"a\"] == 1\n    assert \"a\" in cache\n\n    # next insertion must fail while computing expiration\n    timer.time = 1\n    with pytest.raises(RuntimeError):\n        cache[\"b\"] = 2\n\n    # cache must be exactly as before: no half-existence, no TypeError on 'in'\n    assert len(cache) == 1\n    assert cache.currsize == 1\n    assert \"b\" not in cache  # must not raise TypeError\n    assert \"a\" in cache\n    assert list(cache) == [\"a\"]\n    assert cache[\"a\"] == 1\n    assert dict(cache) == {\"a\": 1}\n\n    # expiration time of existing entry must be unchanged (0+10)\n    timer.time = 9\n    assert \"a\" in cache\n    timer.time = 10\n    assert \"a\" not in cache\n    assert len(cache) == 0\n\n    # cache still usable after failure\n    ttl.fail_on = None\n    timer.time = 11\n    cache[\"c\"] = 3\n    assert \"c\" in cache\n    assert len(cache) == 1\n\n\ndef test_overwrite_generic_failure_atomic():\n    timer = Timer(0)\n    ttl = FailTTL(fail_on=None)\n    cache = TTLCache(maxsize=10, ttl=ttl, timer=timer)\n\n    timer.time = 0\n    cache[\"a\"] = 1\n    timer.time = 1\n    cache[\"b\"] = 2\n    assert list(cache) == [\"a\", \"b\"]\n    assert len(cache) == 2\n    assert cache.currsize == 2\n\n    # try to overwrite existing key, failure must not mutate value/order/expiration\n    ttl.fail_on = 2\n    timer.time = 2\n    with pytest.raises(RuntimeError):\n        cache[\"a\"] = 99\n\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    # value must be old one, not 99\n    assert cache[\"a\"] == 1\n    assert cache[\"b\"] == 2\n    # iteration order must be unchanged (a still first, not moved to end)\n    assert list(cache) == [\"a\", \"b\"]\n    assert dict(cache) == {\"a\": 1, \"b\": 2}\n    # membership must not raise\n    assert \"a\" in cache\n    assert \"b\" in cache\n\n    # expiration times preserved: a 0+10, b 1+10\n    timer.time = 9\n    assert \"a\" in cache and \"b\" in cache\n    timer.time = 10\n    assert \"a\" not in cache\n    assert \"b\" in cache\n    assert len(cache) == 1\n    assert list(cache) == [\"b\"]\n\n\ndef test_new_key_with_evict_generic_failure_atomic():\n    timer = Timer(0)\n    ttl = FailTTL(fail_on=None)\n    cache = TTLCache(maxsize=2, ttl=ttl, timer=timer)\n\n    timer.time = 0\n    cache[\"a\"] = 1\n    timer.time = 1\n    cache[\"b\"] = 2\n    assert list(cache) == [\"a\", \"b\"]\n    assert len(cache) == 2\n    assert cache.currsize == 2\n\n    # inserting c would evict LRU (a); failure must roll back eviction\n    ttl.fail_on = 2\n    timer.time = 2\n    with pytest.raises(RuntimeError):\n        cache[\"c\"] = 3\n\n    assert len(cache) == 2\n    assert cache.currsize == 2\n    assert \"c\" not in cache  # must not raise TypeError\n    assert \"a\" in cache\n    assert \"b\" in cache\n    assert list(cache) == [\"a\", \"b\"]\n    assert cache[\"a\"] == 1\n    assert cache[\"b\"] == 2\n\n    # lru order still correct, and expiration preserved\n    timer.time = 9\n    assert \"a\" in cache\n    timer.time = 10\n    assert \"a\" not in cache\n    assert \"b\" in cache\n\n    # after rollback cache must still evict correctly on next successful insert\n    ttl.fail_on = None\n    # need a fresh cache for eviction check to avoid time going backwards\n    timer2 = Timer(0)\n    ttl2 = FailTTL(fail_on=2)\n    cache2 = TTLCache(maxsize=2, ttl=ttl2, timer=timer2)\n    timer2.time = 0\n    cache2[\"a\"] = 1\n    timer2.time = 1\n    cache2[\"b\"] = 2\n    timer2.time = 2\n    with pytest.raises(RuntimeError):\n        cache2[\"c\"] = 3\n    assert list(cache2) == [\"a\", \"b\"]\n    ttl2.fail_on = None\n    # same time, successful insert should evict a\n    cache2[\"c\"] = 3\n    assert len(cache2) == 2\n    assert \"a\" not in cache2\n    assert \"b\" in cache2\n    assert \"c\" in cache2\n    assert list(cache2) == [\"b\", \"c\"]\n",
