     "n": 1,
     "author": "hand-written",
     "diff": "diff --git a/jinja2/filters.py b/jinja2/filters.py\nindex ed07c4c..72dcb7e 100644\n--- a/jinja2/filters.py\n+++ b/jinja2/filters.py\n@@ -274,11 +274,18 @@ def do_xmlattr(\n     As you can see it automatically prepends a space in front of the item\n     if the filter returned something unless the second parameter is false.\n     \"\"\"\n-    rv = \" \".join(\n-        f'{escape(key)}=\"{escape(value)}\"'\n-        for key, value in d.items()\n-        if value is not None and not isinstance(value, Undefined)\n-    )\n+    items = []\n+\n+    for key, value in d.items():\n+        if value is None or isinstance(value, Undefined):\n+            continue\n+\n+        if re.search(r\"on[a-z]+\\s*=\", key, flags=re.IGNORECASE):\n+            raise ValueError(f\"event handler not allowed in attribute name: {key!r}\")\n+\n+        items.append(f'{escape(key)}=\"{escape(value)}\"')\n+\n+    rv = \" \".join(items)\n \n     if autospace and rv:\n         rv = \" \" + rv\n",
     "visible_passed": true,
     "hidden_passed": false,
