      "test": "```python\nimport pytest\nfrom jinja2 import Environment\nfrom markupsafe import Markup\n\n# Characters that end an attribute name in HTML tokenizer's attribute name state:\n# whitespace (space, \\t, \\n, \\r, \\f), \"/\", \">\", \"=\"\nINVALID_KEYS = [\n    \"a b\",      # space\n    \"a\\tb\",     # tab\n    \"a\\nb\",     # lf\n    \"a\\rb\",     # cr\n    \"a\\fb\",     # ff (\\x0c)\n    \"a/b\",      # solidus\n    \"a>b\",      # greater-than\n    \"a=b\",      # equals\n]\n\n# Simple invalid keys that can be written as literal dict in template source\nLITERAL_INVALID_KEYS = [\"a b\", \"a/b\", \"a>b\", \"a=b\"]\n\nVALID_KEYS = [\n    \"data-foo\",\n    \"foo:bar\",\n    \"foo.bar\",\n    \"foo_bar\",\n    \"foo1\",\n    \"a-1:b.c_d\",\n    \"caf\u00e9\",\n    \"na\u00efve\",\n    \"\u03c9test\",\n    \"\u0442\u0435\u0441\u0442\",\n    \"\u5c5e\u6027\",\n    \"aB0-_.:1\",\n]\n\n\ndef test_xmlattr_rejects_invalid_literal_dict():\n    env = Environment()\n    for key in LITERAL_INVALID_KEYS:\n        # embed key directly as literal dict key in template\n        tmpl_src = \"{{ {'%s': 'x'}|xmlattr }}\" % key\n        tmpl = env.from_string(tmpl_src)\n        with pytest.raises(ValueError):\n            tmpl.render()\n\n\n@pytest.mark.parametrize(\"key\", INVALID_KEYS)\ndef test_xmlattr_rejects_invalid_via_variable_dict(key):\n    env = Environment()\n    tmpl = env.from_string(\"{{ d|xmlattr }}\")\n    with pytest.raises(ValueError):\n        tmpl.render(d={key: \"x\"})\n\n\n@pytest.mark.parametrize(\"key\", INVALID_KEYS)\ndef test_xmlattr_rejects_invalid_via_variable_key(key):\n    env = Environment()\n    tmpl = env.from_string(\"{{ {k: 'x'}|xmlattr }}\")\n    with pytest.raises(ValueError):\n        tmpl.render(k=key)\n\n\ndef test_xmlattr_rejects_example_from_task_variants():\n    env = Environment()\n    # original example (also should still raise)\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'src=1 onerror=alert(1)': 'x'}|xmlattr }}\").render()\n    # other injections that are not event-handler pattern - buggy code misses these\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={\"foo=bar\": \"x\"})\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={\"x>y\": \"x\"})\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={\"x/y\": \"x\"})\n\n\n@pytest.mark.parametrize(\"key\", VALID_KEYS)\ndef test_xmlattr_allows_valid_names_via_variable_key(key):\n    env = Environment()\n    tmpl = env.from_string(\"{{ {k: 'v'}|xmlattr }}\")\n    out = tmpl.render(k=key)\n    # should not raise and should contain the attribute\n    assert f'{key}=\"v\"' in out\n\n\ndef test_xmlattr_allows_valid_names_literal():\n    env = Environment()\n    tmpl = env.from_string(\n        \"{{ {'data-foo': '1', 'foo:bar': '2', 'foo.bar': '3', 'foo_bar': '4', 'a1': '5'}|xmlattr }}\"\n    )\n    out = tmpl.render()\n    for expected in ['data-foo=\"1\"', 'foo:bar=\"2\"', 'foo.bar=\"3\"', 'foo_bar=\"4\"', 'a1=\"5\"']:\n        assert expected in out\n\n\ndef test_xmlattr_allows_non_ascii_literal():\n    env = Environment()\n    tmpl = env.from_string(\"{{ {'caf\u00e9': 'v'}|xmlattr }}\")\n    out = tmpl.render()\n    assert 'caf\u00e9=\"v\"' in out\n\n\ndef test_xmlattr_values_still_escaped():\n    env = Environment()\n    tmpl = env.from_string(\"{{ {'a': '<&>\\\"\\\\''}|xmlattr }}\")\n    out = tmpl.render()\n    # value must be escaped\n    assert \"&lt;\" in out\n    assert \"&amp;\" in out\n    assert \"&gt;\" in out or \"&lt;&amp;&gt;\" in out  # at least lt and amp\n\n\ndef test_xmlattr_none_and_undefined_skipped():\n    env = Environment()\n    tmpl = env.from_string(\n        \"{{ {'foo': 42, 'bar': 23, 'fish': none, 'spam': missing, 'blub:blub': '<?>'}|xmlattr }}\"\n    )\n    out = tmpl.render().split()\n    assert len(out) == 3\n    assert 'foo=\"42\"' in out\n    assert 'bar=\"23\"' in out\n    assert 'blub:blub=\"&lt;?&gt;\"' in out\n    # ensure invalid key with none value does NOT need to raise (skipped)\n    tmpl2 = env.from_string(\"{{ d|xmlattr }}\")\n    out2 = tmpl2.render(d={\"a b\": none, \"ok\": \"1\"})\n    assert 'ok=\"1\"' in out\n",
