      "status": "confirmed",
      "test": "import pytest\nfrom jinja2 import Environment\n\n\n@pytest.fixture\ndef env():\n    return Environment()\n\n\n# Invalid chars that end an attribute name in the HTML tokenizer\n# attribute-name state: space, \\t, \\n, \\r, \\f, \"/\", \">\", \"=\"\nINVALID_KEYS = [\n    \"a b\",           # space\n    \"a\\tb\",          # tab\n    \"a\\nb\",          # newline\n    \"a\\rb\",          # carriage return\n    \"a\\fb\",          # form feed\n    \"x=y\",           # equals\n    \"a/b\",           # slash\n    \"a>b\",           # greater-than\n    \"foo bar\",       # space again, simple\n    \"a=b=c\",         # multiple equals\n    \"/leading\",      # starting with /\n    \">leading\",      # starting with >\n    \"=leading\",      # starting with =\n]\n\nVALID_KEYS = [\n    \"foo\",\n    \"data-value\",    # -\n    \"xml:lang\",      # :\n    \"my.attr\",       # .\n    \"_private\",      # _\n    \"a1\",            # digit\n    \"bar2\",          # digit\n    \"caf\u00e9\",          # non-ASCII\n    \"na\u00efve\",         # non-ASCII\n    \"a-b:c.d_e1\",    # combination of allowed punct\n    \"blub:blub\",     # from original test\n    \"FOO\",           # uppercase\n]\n\n\n@pytest.mark.parametrize(\"key\", INVALID_KEYS)\ndef test_xmlattr_invalid_keys_literal(env, key):\n    # literal dict in template\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\".replace(\"k\", repr(key)) if False else None)\n        # Use python construction to avoid jinja quoting issues: build template\n        # with literal and render, but we can also just pass via variable.\n        # To test literal path we render a template string that contains the key literally.\n        # Build template safely:\n        tmpl = env.from_string(\"{{ d|xmlattr }}\")\n        tmpl.render(d={key: \"1\"})\n\n\n@pytest.mark.parametrize(\"key\", INVALID_KEYS)\ndef test_xmlattr_invalid_keys_via_variable_dict(env, key):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ attrs|xmlattr }}\").render(attrs={key: \"1\"})\n\n\n@pytest.mark.parametrize(\"key\", INVALID_KEYS)\ndef test_xmlattr_invalid_keys_via_variable_key(env, key):\n    # key passed as variable used as dict key\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"1\"})\n    # also via jinja variable key expression {k: '1'}\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=key)\n\n\ndef test_xmlattr_literal_space_raises(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a b': '1'}|xmlattr }}\").render()\n\n\ndef test_xmlattr_equals_raises(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'x=y': '1'}|xmlattr }}\").render()\n\n\ndef test_xmlattr_slash_raises(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a/b': '1'}|xmlattr }}\").render()\n\n\ndef test_xmlattr_gt_raises(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a>b': '1'}|xmlattr }}\").render()\n\n\ndef test_xmlattr_variable_dict_space_raises(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ data|xmlattr }}\").render(data={\"src=1 onerror=alert(1)\": \"x\"})\n\n\ndef test_xmlattr_variable_key_space_raises(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {mykey: '1'}|xmlattr }}\").render(mykey=\"a b\")\n\n\ndef test_xmlattr_variable_key_equals_raises(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {mykey: '1'}|xmlattr }}\").render(mykey=\"x=y\")\n\n\ndef test_xmlattr_original_example_still_raises(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'src=1 onerror=alert(1)': 'my_class'}|xmlattr }}\").render()\n\n\n@pytest.mark.parametrize(\"key\", VALID_KEYS)\ndef test_xmlattr_valid_keys_still_work(env, key):\n    # should not raise, should produce valid attribute\n    out = env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"1\"})\n    assert f'{key}=\"1\"' in out\n\n\ndef test_xmlattr_valid_keys_with_escaping_still_work(env):\n    tmpl = env.from_string(\"{{ {'foo': 42, 'bar': 23, 'fish': none, 'blub:blub': '<?>'}|xmlattr }}\")\n    out = tmpl.render().split()\n    assert len(out) == 3\n    assert 'foo=\"42\"' in out\n    assert 'bar=\"23\"' in out\n    assert 'blub:blub=\"&lt;?&gt;\"' in out\n",
