      "test": "import pytest\nfrom jinja2 import Environment\n\n\ndef test_literal_invalid_keys_must_raise():\n    env = Environment()\n    # Each key contains a character that ends an attribute name in\n    # HTML tokenizer's attribute name state: whitespace, '/', '>', '='\n    invalid_keys = [\n        \"a b\",          # space\n        \"a\\tb\",          # tab\n        \"a\\nb\",          # lf\n        \"a\\rb\",          # cr\n        \"a\\fb\",          # ff\n        \"a/b\",           # slash\n        \"a>b\",           # gt\n        \"a=b\",           # equals\n        \"a b/c\",         # combined\n        \"foo bar\",       # without on* pattern - must still be blocked\n    ]\n    for key in invalid_keys:\n        with pytest.raises(ValueError):\n            env.from_string(\"{{ {k: '1'}|xmlattr }}\").render(k=key)\n\n\ndef test_literal_invalid_keys_literal_dict():\n    env = Environment()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a b': '1'}|xmlattr }}\").render()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a/b': '1'}|xmlattr }}\").render()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a>b': '1'}|xmlattr }}\").render()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a=b': '1'}|xmlattr }}\").render()\n\n\ndef test_variable_dict_invalid_keys():\n    # dict passed in as variable\n    env = Environment()\n    tmpl = env.from_string(\"{{ attrs|xmlattr }}\")\n    for key in [\"a b\", \"a/b\", \"a>b\", \"a=b\", \"a\\tb\"]:\n        with pytest.raises(ValueError):\n            tmpl.render(attrs={key: \"1\"})\n\n\ndef test_variable_key_invalid():\n    # key passed in as variable via dict construction\n    env = Environment()\n    tmpl = env.from_string(\"{{ {k: 'v'}|xmlattr }}\")\n    for key in [\"a b\", \"a/b\", \"a>b\", \"a=b\", \"a\\nb\"]:\n        with pytest.raises(ValueError):\n            tmpl.render(k=key)\n\n\ndef test_valid_attribute_names_still_work():\n    env = Environment()\n    valid_keys = [\n        \"foo\",\n        \"data-value\",   # hyphen\n        \"data:value\",   # colon - present in existing test as blub:blub\n        \"a.b\",          # dot\n        \"my_attr\",      # underscore\n        \"a1\",           # digits\n        \"attr2\",\n        \"caf\u00e9\",         # non-ASCII\n        \"na\u00efve\",\n        \"onclick\",      # event handler name alone has no terminator, must be allowed\n        \"onerror\",\n        \"custom-attr_123:foo.bar\",\n    ]\n    for key in valid_keys:\n        out = env.from_string(\"{{ {k: 'v'}|xmlattr }}\").render(k=key)\n        assert f'{key}=\"v\"' in out\n\n    # original valid test from tests/test_xmlattr.py must still pass\n    tmpl = env.from_string(\n        \"{{ {'foo': 42, 'bar': 23, 'fish': none, \"\n        \"'spam': missing, 'blub:blub': '<?>'}|xmlattr }}\"\n    )\n    out = tmpl.render().split()\n    assert len(out) == 3\n    assert 'foo=\"42\"' in out\n    assert 'bar=\"23\"' in out\n    assert 'blub:blub=\"&lt;?&gt;\"' in out\n\n\ndef test_original_exploit_also_blocked():\n    env = Environment()\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'src=1 onerror=alert(1)': 'x'}|xmlattr }}\").render()\n    # same via variable dict / variable key\n    tmpl = env.from_string(\"{{ attrs|xmlattr }}\")\n    with pytest.raises(ValueError):\n        tmpl.render(attrs={\"src=1 onerror=alert(1)\": \"x\"})\n    tmpl2 = env.from_string(\"{{ {k: 'x'}|xmlattr }}\")\n    with pytest.raises(ValueError):\n        tmpl2.render(k=\"src=1 onerror=alert(1)\")\n",
