      "test": "import pytest\nfrom jinja2 import Environment\n\n@pytest.fixture\ndef env():\n    return Environment()\n\n# invalid keys that must be rejected per HTML attribute-name-state\n# bare '=', '\"', \"'\", '>', '/', bare whitespace (space, tab, newline, etc.)\nINVALID_KEYS_SIMPLE = [\"a=b\", \"a b\", \"a/b\", \"a>b\"]\nINVALID_KEYS_ALL = [\"a=b\", \"a b\", \"a\\tb\", \"a\\nb\", \"a\\fb\", \"a\\rb\", 'a\"b', \"a'b\", \"a>b\", \"a/b\"]\n\ndef test_xmlattr_literal_equals(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a=b': 'x'}|xmlattr }}\").render()\n\ndef test_xmlattr_literal_space(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a b': 'x'}|xmlattr }}\").render()\n\ndef test_xmlattr_literal_slash(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a/b': 'x'}|xmlattr }}\").render()\n\ndef test_xmlattr_literal_gt(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {'a>b': 'x'}|xmlattr }}\").render()\n\ndef test_xmlattr_rejects_via_dict_variable(env):\n    for key in INVALID_KEYS_ALL:\n        with pytest.raises(ValueError):\n            env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"x\"})\n\ndef test_xmlattr_rejects_via_key_variable(env):\n    for key in INVALID_KEYS_ALL:\n        with pytest.raises(ValueError):\n            env.from_string(\"{{ {k: 'x'}|xmlattr }}\").render(k=key)\n\ndef test_xmlattr_rejects_quote_via_variable(env):\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={'a\"b': \"x\"})\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ d|xmlattr }}\").render(d={\"a'b\": \"x\"})\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: 'x'}|xmlattr }}\").render(k='a\"b')\n    with pytest.raises(ValueError):\n        env.from_string(\"{{ {k: 'x'}|xmlattr }}\").render(k=\"a'b\")\n\ndef test_xmlattr_rejects_whitespace_variants(env):\n    for key in [\"a\\tb\", \"a\\nb\", \"a\\fb\", \"a\\rb\"]:\n        with pytest.raises(ValueError):\n            env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"v\"})\n        with pytest.raises(ValueError):\n            env.from_string(\"{{ {k: 'v'}|xmlattr }}\").render(k=key)\n\ndef test_xmlattr_valid_names_still_work(env):\n    valid = [\"foo\", \"foo-bar\", \"foo:bar\", \"foo.bar\", \"foo_bar\", \"a1\", \"data-value_1:test.case\", \"caf\u00e9\"]\n    for key in valid:\n        out = env.from_string(\"{{ d|xmlattr }}\").render(d={key: \"v\"})\n        assert f'{key}=\"v\"' in out\n\ndef test_xmlattr_valid_literal_still_work(env):\n    tmpl = env.from_string(\"{{ {'foo': 42, 'bar': 23, 'fish': none, 'spam': missing, 'blub:blub': '<?>'}|xmlattr }}\")\n    out = tmpl.render().split()\n    assert len(out) == 3\n    assert 'foo=\"42\"' in out\n    assert 'bar=\"23\"' in out\n    assert 'blub:blub=\"&lt;?&gt;\"' in out\n\ndef test_xmlattr_none_and_undefined_skipped(env):\n    out = env.from_string(\"{{ {'a': '1', 'b': none}|xmlattr }}\").render()\n    assert 'a=\"1\"' in out\n    assert 'b=' not in out\n    out2 = env.from_string(\"{{ {'a': '1', 'b': missing}|xmlattr }}\").render()\n    assert 'a=\"1\"' in out2\n    assert 'b=' not in out2\n\ndef test_xmlattr_escaping_and_autospace(env):\n    out = env.from_string(\"{{ {'x': '<>\\\"&'}|xmlattr }}\").render()\n    assert 'x=\"' in out\n    assert '&lt;' in out\n    assert '&gt;' in out\n    assert '&amp;' in out\n    # autospace true by default prepends space\n    assert out.startswith(' ')\n    out2 = env.from_string(\"{{ {'x': '1'}|xmlattr(false) }}\").render()\n    assert not out2.startswith(' ')\n    assert out2 == 'x=\"1\"'\n",
